// Union européenne (banque 3) : droit de l'UE (sources, actes, principes, grands arrêts,
// jurisprudence française), compétences, recours devant la CJUE, budget (CFP, ressources propres,
// NextGenerationEU, conditionnalité), marché intérieur, citoyenneté, concurrence, commerce, PAC,
// cohésion, UEM, PESC/PSDC, JAI et Schengen, social, climat et énergie, numérique, fiscalité,
// droits fondamentaux (Charte, CEDH, Conseil de l'Europe).
BANK.push(
{id:"ue3-001",t:"ue",q:"Lequel de ces ensembles relève du droit primaire de l'Union européenne ?",o:["Les règlements et les directives","Les décisions de la Commission","Les arrêts des juridictions nationales","Le TUE, le TFUE, leurs protocoles et la Charte des droits fondamentaux"],a:3,e:"Le droit primaire (traités, protocoles et annexes, Charte) est au sommet de la hiérarchie des normes de l'Union.",x:"Les actes adoptés par les institutions sur le fondement des traités (règlements, directives, décisions) forment le droit dérivé.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/la-hierarchie-des-normes-de-droit-de-l-union-europeenne/"],s:"Banque UE"},
{id:"ue3-002",t:"ue",q:"Quel article du TFUE énumère les actes juridiques de l'Union : règlement, directive, décision, recommandation et avis ?",o:["Article 258","Article 267","Article 288","Article 314"],a:2,e:"L'article 288 TFUE définit la portée de chaque acte. L'article 258 concerne le manquement, le 267 le renvoi préjudiciel, le 314 la procédure budgétaire.",u:["https://european-union.europa.eu/institutions-law-budget/law/types-legislation_fr"],s:"TFUE, art. 288"},
{id:"ue3-003",t:"ue",q:"Une directive non transposée dans le délai, dont une disposition est inconditionnelle et suffisamment précise, peut être invoquée par un particulier :",o:["Contre un autre particulier uniquement","Contre personne tant qu'elle n'est pas transposée","Seulement devant la Cour européenne des droits de l'homme","Contre l'État (effet direct vertical)"],a:3,e:"Jurisprudence Van Duyn (1974) et Ratti (1979) : l'État ne peut pas se prévaloir de sa propre carence.",x:"L'effet direct horizontal (entre particuliers) des directives est en revanche refusé (Marshall, 1986 ; Faccini Dori, 1994).",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/qu-est-ce-qu-une-directive/"],s:"CJCE, Van Duyn, 1974"},
{id:"ue3-004",t:"ue",q:"Selon la Cour de justice (Marshall, 1986 ; Faccini Dori, 1994), une directive non transposée peut-elle être invoquée par un particulier contre un autre particulier ?",o:["Non : la Cour refuse l'effet direct horizontal des directives","Oui, dans tous les cas","Oui, si la Commission l'autorise","Seulement en matière fiscale"],a:0,e:"Une directive ne peut pas, par elle-même, créer d'obligations à la charge d'un particulier.",x:"La victime peut demander une interprétation conforme du droit national ou rechercher la responsabilité de l'État (Francovich).",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/qu-est-ce-qu-une-directive/"],s:"CJCE, Faccini Dori, 1994"},
{id:"ue3-005",t:"ue",q:"Comment appelle-t-on le contrôle exercé par des comités de représentants des États membres sur les actes d'exécution adoptés par la Commission (art. 291 TFUE) ?",o:["Le trilogue","La coopération renforcée","Le mécanisme d'alerte précoce","La comitologie"],a:3,e:"Les procédures de comité (examen, consultative) sont fixées par le règlement (UE) n° 182/2011.",u:["https://fr.wikipedia.org/wiki/Comitologie"],s:"TFUE, art. 291"},
{id:"ue3-006",t:"ue",q:"La procédure législative ordinaire (art. 294 TFUE) comporte au maximum :",o:["Une lecture","Deux lectures","Trois lectures, avec un comité de conciliation avant la troisième","Quatre lectures"],a:2,e:"Première et deuxième lectures au Parlement et au Conseil ; en cas de désaccord persistant, un comité de conciliation est réuni, puis intervient une troisième lecture.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/infographie-la-procedure-legislative-de-l-union-europeenne/"],s:"TFUE, art. 294"},
{id:"ue3-008",t:"ue",q:"Quel article du TUE régit la révision des traités ?",o:["Article 49","Article 50","Article 7","Article 48"],a:3,e:"Procédure ordinaire (convention puis conférence intergouvernementale) ou simplifiée ; toute modification doit être ratifiée par tous les États membres.",x:"Article 49 : adhésion ; article 50 : retrait ; article 7 : protection des valeurs.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/le-traite-sur-l-union-europeenne-tue/"],s:"TUE, art. 48"},
{id:"ue3-009",t:"ue",q:"Lorsqu'il ne fixe pas lui-même sa date d'entrée en vigueur, un acte législatif publié au Journal officiel de l'Union européenne entre en vigueur :",o:["Le jour de sa publication","Le vingtième jour suivant sa publication","Trois mois après sa publication","Après sa ratification par les parlements nationaux"],a:1,e:"Art. 297 TFUE.",u:["https://fr.wikipedia.org/wiki/Journal_officiel_de_l'Union_européenne"],s:"TFUE, art. 297"},
{id:"ue3-010",t:"ue",q:"Sur quel article de la Constitution le Conseil constitutionnel fonde-t-il, depuis sa décision du 10 juin 2004, l'exigence constitutionnelle de transposition des directives ?",o:["Article 88-1","Article 55","Article 89","Article 61-1"],a:0,e:"Décision n° 2004-496 DC (loi pour la confiance dans l'économie numérique) : la transposition résulte d'une exigence constitutionnelle.",x:"Limite : la transposition ne peut aller à l'encontre d'une règle ou d'un principe inhérent à l'identité constitutionnelle de la France (décision n° 2006-540 DC).",u:["https://www.conseil-constitutionnel.fr/decision/2004/2004496DC.htm"],s:"Cons. const., 10 juin 2004"},
{id:"ue3-011",t:"ue",q:"Lorsque le Conseil constitutionnel, saisi sur le fondement de l'article 54, juge qu'un traité européen comporte une clause contraire à la Constitution, quelle en est la conséquence ?",o:["Le traité est annulé","La Cour de justice de l'Union est saisie","Un référendum devient obligatoire","La ratification ne peut intervenir qu'après une révision de la Constitution"],a:3,e:"Ce fut le cas pour Maastricht (révision du 25 juin 1992), Amsterdam (1999), le traité constitutionnel (2005) et Lisbonne (2008).",u:["https://www.conseil-constitutionnel.fr/decision/1992/92308DC.htm"],s:"Constitution, art. 54"},
{id:"ue3-012",t:"ue",q:"Par quel arrêt de 1989 le Conseil d'État a-t-il accepté de faire prévaloir un traité sur une loi postérieure contraire ?",o:["L'arrêt Nicolo","L'arrêt Jacques Vabre","L'arrêt Sarran","L'arrêt Blanco"],a:0,e:"CE, Ass., 20 octobre 1989, Nicolo, sur le fondement de l'article 55 de la Constitution ; il abandonne la jurisprudence des Semoules (1968).",u:["https://fr.wikipedia.org/wiki/Arrêt_Nicolo"],s:"CE, 1989, Nicolo"},
{id:"ue3-013",t:"ue",q:"Quelle juridiction a, dès 1975 avec l'arrêt Société des cafés Jacques Vabre, fait prévaloir le traité de Rome sur une loi postérieure ?",o:["Le Conseil d'État","Le Conseil constitutionnel","La Cour de justice des Communautés européennes","La Cour de cassation"],a:3,e:"Cass., chambre mixte, 24 mai 1975. Le Conseil d'État ne l'a suivie qu'en 1989 (Nicolo).",u:["https://fr.wikipedia.org/wiki/Arrêt_Jacques_Vabre"],s:"Cass., 1975, Jacques Vabre"},
{id:"ue3-014",t:"ue",q:"Dans sa décision IVG du 15 janvier 1975, qu'a jugé le Conseil constitutionnel ?",o:["Qu'il ne lui appartient pas, saisi au titre de l'article 61, d'examiner la conformité d'une loi à un traité","Que le droit communautaire prime la Constitution","Que les directives ont un effet direct","Que la Convention européenne des droits de l'homme a valeur constitutionnelle"],a:0,e:"Le contrôle de conventionnalité des lois revient donc aux juges ordinaires : Cour de cassation (1975), Conseil d'État (1989).",u:["https://www.conseil-constitutionnel.fr/decision/1975/7454DC.htm"],s:"Cons. const., 15 janvier 1975"},
{id:"ue3-015",t:"ue",q:"Selon l'arrêt Sarran du Conseil d'État (1998), dans l'ordre juridique interne :",o:["Les traités priment la Constitution","Les règlements européens priment la Constitution","La Convention européenne des droits de l'homme a valeur constitutionnelle","La suprématie conférée aux engagements internationaux ne s'applique pas aux dispositions de nature constitutionnelle"],a:3,e:"CE, Ass., 30 octobre 1998, Sarran, Levacher et autres ; même solution pour la Cour de cassation (Fraisse, 2000).",s:"CE, 1998, Sarran"},
{id:"ue3-016",t:"ue",q:"Qu'a admis le Conseil d'État dans l'arrêt Perreux (2009) ?",o:["Qu'un justiciable peut invoquer, contre un acte administratif non réglementaire, les dispositions précises et inconditionnelles d'une directive non transposée dans les délais","Que les directives priment la Constitution","Que le juge administratif peut contrôler la constitutionnalité des lois","Que les règlements européens doivent être transposés"],a:0,e:"CE, Ass., 30 octobre 2009, Mme Perreux : abandon de la jurisprudence Cohn-Bendit (1978).",s:"CE, 2009, Perreux"},
{id:"ue3-017",t:"ue",q:"En vertu du principe de proportionnalité (art. 5 § 4 TUE) :",o:["Le poids de chaque État au Conseil est proportionnel à sa contribution au budget","Les sièges au Parlement européen sont strictement proportionnels à la population","Les amendes infligées aux États sont proportionnelles à leur PIB","Le contenu et la forme de l'action de l'Union n'excèdent pas ce qui est nécessaire pour atteindre les objectifs des traités"],a:3,e:"Avec l'attribution et la subsidiarité, il encadre l'exercice des compétences de l'Union.",x:"La répartition des sièges au Parlement européen suit une proportionnalité dégressive.",u:["https://fr.wikipedia.org/wiki/Principe_de_proportionnalité"],s:"TUE, art. 5 § 4"},
{id:"ue3-018",t:"ue",q:"Dans quels domaines le principe de subsidiarité s'applique-t-il ?",o:["Dans les domaines qui ne relèvent pas de la compétence exclusive de l'Union","Uniquement dans les domaines de compétence exclusive","Dans tous les domaines, y compris la politique monétaire de la zone euro","Uniquement en matière budgétaire"],a:0,e:"Art. 5 § 3 TUE : là où seule l'Union peut agir, la question de la subsidiarité ne se pose pas.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/qu-est-ce-que-le-principe-de-subsidiarite/"],s:"TUE, art. 5 § 3"},
{id:"ue3-019",t:"ue",q:"Selon la Cour de justice (Internationale Handelsgesellschaft, 1970), la primauté du droit communautaire s'exerce à l'égard :",o:["Des seules lois antérieures","Des seuls actes réglementaires","Des seules normes que l'État a acceptées","De toutes les normes nationales, y compris constitutionnelles"],a:3,e:"L'invocation d'atteintes aux droits fondamentaux tels que formulés par la Constitution d'un État ne peut affecter la validité d'un acte communautaire.",x:"En France, le Conseil d'État (Sarran, 1998) et le Conseil constitutionnel maintiennent la suprématie de la Constitution dans l'ordre interne.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/le-droit-de-l-union-europeenne/"],s:"CJCE, 1970"},
{id:"ue3-020",t:"ue",q:"Le principe de primauté du droit de l'Union est-il inscrit dans le texte des traités ?",o:["Non : il est d'origine jurisprudentielle, rappelé par une déclaration annexée au traité de Lisbonne","Oui, à l'article 1er du TUE","Oui, à l'article 1er de la Charte des droits fondamentaux","Non, et la Cour de justice l'a abandonné en 2009"],a:0,e:"La Constitution européenne de 2004 l'inscrivait ; après son échec, il figure dans la déclaration n° 17 relative à la primauté.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/droit-europeen-droit-national-quels-liens-entretiennent-ils/"],s:"Déclaration n° 17"},
{id:"ue3-021",t:"ue",q:"Que permet l'effet direct reconnu par l'arrêt Van Gend en Loos (1963) ?",o:["Aux États de ne pas appliquer un traité","À la Commission d'adopter seule des lois","Au Parlement européen de lever des impôts","Aux particuliers d'invoquer une norme européenne devant leur juge national"],a:3,e:"La Cour y voit dans la Communauté un nouvel ordre juridique dont les sujets sont les États mais aussi leurs ressortissants.",x:"L'affaire portait sur la hausse d'un droit de douane néerlandais, contraire au traité CEE.",u:["https://fr.wikipedia.org/wiki/Droit_de_l'Union_européenne"],s:"CJCE, 1963"},
{id:"ue3-022",t:"ue",q:"Le litige à l'origine de l'arrêt Costa contre ENEL (1964) portait sur :",o:["La nationalisation de l'électricité en Italie","Un droit de douane néerlandais","La commercialisation d'une liqueur de cassis","Le transfert d'un footballeur"],a:0,e:"Un actionnaire d'une société nationalisée contestait la loi italienne ; la Cour juge que le droit né du traité ne peut se voir opposer un texte interne quel qu'il soit : c'est la primauté.",u:["https://fr.wikipedia.org/wiki/Arrêt_Costa_contre_ENEL"],s:"CJCE, 1964, Costa"},
{id:"ue3-023",t:"ue",q:"Que définit l'arrêt Dassonville (1974) ?",o:["La citoyenneté européenne","Les aides d'État","Le principe de subsidiarité","Les mesures d'effet équivalent à des restrictions quantitatives"],a:3,e:"Toute réglementation commerciale des États susceptible d'entraver directement ou indirectement, actuellement ou potentiellement, le commerce intracommunautaire (art. 34 TFUE).",u:["https://www.touteleurope.eu/economie-et-social/la-libre-circulation-des-marchandises/"],s:"CJCE, 1974, Dassonville"},
{id:"ue3-024",t:"ue",q:"À quoi l'arrêt Bosman (1995) a-t-il appliqué la libre circulation des travailleurs ?",o:["Aux sportifs professionnels, en condamnant les indemnités de transfert en fin de contrat et les quotas de joueurs ressortissants d'autres États membres","Aux fonctionnaires nationaux exerçant la puissance publique","Aux étudiants en mobilité Erasmus","Aux travailleurs des pays tiers"],a:0,e:"Jean-Marc Bosman, footballeur belge, contestait les règles de transfert de l'UEFA.",u:["https://fr.wikipedia.org/wiki/Arrêt_Bosman"],s:"CJCE, 1995, Bosman"},
{id:"ue3-025",t:"ue",q:"Selon l'arrêt Foto-Frost (1987), qui peut constater l'invalidité d'un acte de l'Union ?",o:["Toute juridiction nationale","Les seules cours suprêmes nationales","La Commission européenne","La Cour de justice de l'Union, à l'exclusion des juridictions nationales"],a:3,e:"Le juge national peut écarter un moyen d'invalidité ; en cas de doute sérieux sur la validité, il doit saisir la Cour à titre préjudiciel.",s:"CJCE, 1987"},
{id:"ue3-026",t:"ue",q:"Selon l'arrêt CILFIT (1982), une juridiction statuant en dernier ressort peut notamment se dispenser d'un renvoi préjudiciel lorsque :",o:["L'application correcte du droit de l'Union s'impose avec une évidence qui ne laisse place à aucun doute raisonnable","L'enjeu financier du litige est faible","Le gouvernement s'y oppose","La question porte sur la fiscalité"],a:0,e:"C'est la théorie de « l'acte clair » ; la dispense vaut aussi si la question n'est pas pertinente ou a déjà été tranchée par la Cour.",s:"CJCE, 1982"},
{id:"ue3-027",t:"ue",q:"L'arrêt Defrenne (1976) a reconnu l'effet direct du principe :",o:["De libre circulation des capitaux","De subsidiarité","De non-cumul des mandats","D'égalité de rémunération entre les femmes et les hommes"],a:3,e:"Gabrielle Defrenne, hôtesse de l'air de la Sabena, invoquait l'article 119 du traité CEE (aujourd'hui art. 157 TFUE), y compris contre un employeur privé.",s:"CJCE, 1976"},
{id:"ue3-028",t:"ue",q:"Avant la Charte, comment la Cour de justice protégeait-elle les droits fondamentaux (arrêts Stauder, 1969 ; Nold, 1974) ?",o:["En tant que principes généraux du droit, inspirés des traditions constitutionnelles communes et de la Convention européenne des droits de l'homme","Elle refusait de les contrôler","En appliquant la Constitution allemande","En renvoyant les affaires à la Cour de Strasbourg"],a:0,e:"Cette jurisprudence est consacrée à l'article 6 § 3 TUE.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/la-charte-des-droits-fondamentaux-de-l-union-europeenne/"],s:"TUE, art. 6 § 3"},
{id:"ue3-029",t:"ue",q:"Quel principe, posé à l'article 4 § 3 TUE, impose à l'Union et aux États membres de se respecter et de s'assister mutuellement dans l'accomplissement des missions découlant des traités ?",o:["La subsidiarité","La proportionnalité","La préférence communautaire","La coopération loyale"],a:3,e:"Les États prennent toute mesure propre à assurer l'exécution de leurs obligations et s'abstiennent de toute mesure susceptible de mettre en péril les objectifs de l'Union.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/le-traite-sur-l-union-europeenne-tue/"],s:"TUE, art. 4 § 3"},
{id:"ue3-030",t:"ue",q:"Selon l'article 4 § 2 TUE, la sécurité nationale :",o:["Reste de la seule responsabilité de chaque État membre","Relève de la compétence exclusive de l'Union","Est une compétence partagée","Est confiée à l'OTAN par les traités"],a:0,e:"Le même article impose à l'Union de respecter l'identité nationale des États, inhérente à leurs structures fondamentales politiques et constitutionnelles.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/la-repartition-des-competences-entre-l-union-europeenne-et-les-etats-membres/"],s:"TUE, art. 4 § 2"},
{id:"ue3-031",t:"ue",q:"Laquelle de ces compétences n'est pas une compétence exclusive de l'Union (art. 3 TFUE) ?",o:["L'union douanière","L'établissement des règles de concurrence nécessaires au fonctionnement du marché intérieur","La conservation des ressources biologiques de la mer dans le cadre de la politique commune de la pêche","La protection des consommateurs"],a:3,e:"La protection des consommateurs est une compétence partagée (art. 4 TFUE).",x:"Compétences exclusives : union douanière, règles de concurrence du marché intérieur, politique monétaire de la zone euro, conservation des ressources biologiques de la mer, politique commerciale commune, conclusion de certains accords internationaux.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/la-repartition-des-competences-entre-l-union-europeenne-et-les-etats-membres/"],s:"TFUE, art. 3"},
{id:"ue3-032",t:"ue",q:"Lequel de ces domaines relève d'une compétence partagée entre l'Union et les États membres (art. 4 TFUE) ?",o:["L'environnement","La politique monétaire de la zone euro","L'union douanière","La culture"],a:0,e:"Sont notamment partagés : marché intérieur, cohésion, agriculture et pêche, environnement, protection des consommateurs, transports, énergie, espace de liberté, de sécurité et de justice.",x:"La culture relève des compétences d'appui (art. 6 TFUE).",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/la-repartition-des-competences-entre-l-union-europeenne-et-les-etats-membres/"],s:"TFUE, art. 4"},
{id:"ue3-033",t:"ue",q:"Lequel de ces domaines relève des compétences d'appui, de coordination ou de complément (art. 6 TFUE) ?",o:["L'agriculture","Le marché intérieur","Les transports","L'éducation, la formation professionnelle, la jeunesse et le sport"],a:3,e:"Art. 6 : santé humaine, industrie, culture, tourisme, éducation, formation, jeunesse et sport, protection civile, coopération administrative. L'Union n'y harmonise pas les législations nationales.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/la-repartition-des-competences-entre-l-union-europeenne-et-les-etats-membres/"],s:"TFUE, art. 6"},
{id:"ue3-034",t:"ue",q:"Dans un domaine de compétence partagée, les États membres exercent leur compétence :",o:["Dans la mesure où l'Union n'a pas exercé la sienne","Jamais","Seulement avec l'autorisation de la Commission","Seulement s'ils sont au moins neuf"],a:0,e:"Art. 2 § 2 TFUE ; ils l'exercent à nouveau si l'Union a décidé de cesser d'exercer la sienne.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/la-repartition-des-competences-entre-l-union-europeenne-et-les-etats-membres/"],s:"TFUE, art. 2"},
{id:"ue3-035",t:"ue",q:"Dans un domaine de compétence exclusive de l'Union, les États membres peuvent légiférer :",o:["Librement, en parallèle de l'Union","Après simple notification à la Commission","À condition de respecter la subsidiarité","Seulement s'ils y sont habilités par l'Union ou pour mettre en œuvre ses actes"],a:3,e:"Art. 2 § 1 TFUE.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/la-repartition-des-competences-entre-l-union-europeenne-et-les-etats-membres/"],s:"TFUE, art. 2"},
{id:"ue3-036",t:"ue",q:"Sur quel article du TFUE la Commission fonde-t-elle un recours en manquement contre un État membre ?",o:["Article 258","Article 263","Article 265","Article 267"],a:0,e:"Art. 258 (Commission), 259 (un État contre un autre), 260 (exécution de l'arrêt et sanctions pécuniaires). Les art. 263, 265 et 267 portent sur l'annulation, la carence et le renvoi préjudiciel.",u:["https://fr.wikipedia.org/wiki/Recours_en_manquement"],s:"TFUE, art. 258"},
{id:"ue3-037",t:"ue",q:"Avant de saisir la Cour d'un recours en manquement, la Commission adresse à l'État :",o:["Une lettre de mise en demeure, puis un avis motivé","Une amende immédiate","Une question préjudicielle","Une décision de suspension des fonds européens"],a:0,e:"Si l'État ne se conforme pas à l'avis motivé dans le délai fixé, la Commission peut saisir la Cour de justice.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/podcast-comment-l-ue-fait-elle-respecter-le-droit-europeen/"],s:"TFUE, art. 258"},
{id:"ue3-038",t:"ue",q:"Quels requérants sont dits « privilégiés » dans le recours en annulation (art. 263 TFUE) ?",o:["Les particuliers et les entreprises","Les collectivités territoriales","Les partenaires sociaux européens","Les États membres, le Parlement européen, le Conseil et la Commission"],a:3,e:"Ils n'ont pas à justifier d'un intérêt à agir. La Cour des comptes, la BCE et le Comité des régions peuvent agir pour la sauvegarde de leurs prérogatives.",u:["https://www.touteleurope.eu/institutions/la-cour-de-justice-de-l-union-europeenne-cjue/"],s:"TFUE, art. 263"},
{id:"ue3-039",t:"ue",q:"Un particulier peut-il former un recours en annulation contre un acte de l'Union dont il n'est pas le destinataire ?",o:["Oui, s'il est concerné directement et individuellement, ou directement s'il s'agit d'un acte réglementaire sans mesure d'exécution","Non, jamais","Oui, sans aucune condition","Seulement par l'intermédiaire du Médiateur européen"],a:0,e:"Art. 263, al. 4 TFUE ; l'affectation individuelle est appréciée strictement depuis l'arrêt Plaumann (1963).",u:["https://www.touteleurope.eu/institutions/la-cour-de-justice-de-l-union-europeenne-cjue/"],s:"TFUE, art. 263"},
{id:"ue3-040",t:"ue",q:"Quel est l'effet d'un arrêt rendu par la Cour de justice sur renvoi préjudiciel ?",o:["Il tranche lui-même le litige au fond","Il n'a qu'une valeur consultative","Il peut être réformé par le Conseil d'État","Il lie le juge national qui l'a saisie, lequel tranche ensuite le litige"],a:3,e:"L'interprétation donnée s'impose en pratique à toutes les juridictions des États membres.",u:["https://fr.wikipedia.org/wiki/Renvoi_préjudiciel"],s:"TFUE, art. 267"},
{id:"ue3-041",t:"ue",q:"Devant quelle juridiction un particulier engage-t-il en première instance la responsabilité extracontractuelle de l'Union (art. 340 TFUE) ?",o:["Le Tribunal de l'Union européenne","La Cour européenne des droits de l'homme","Le tribunal administratif de son domicile","La Cour des comptes européenne"],a:0,e:"Le Tribunal juge en premier ressort les recours directs des particuliers (annulation, carence, responsabilité) ; ses décisions peuvent faire l'objet d'un pourvoi limité aux questions de droit devant la Cour.",u:["https://www.touteleurope.eu/institutions/le-tribunal-de-premiere-instance-de-l-union-europeenne/"],s:"TFUE, art. 256 et 340"},
{id:"ue3-042",t:"ue",q:"Combien de juges la Cour de justice compte-t-elle ?",o:["9","15","27","54"],a:2,e:"Un juge par État membre, soit 27 juges, assistés de onze avocats généraux.",u:["https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/court-justice-european-union-cjeu_fr"],s:"TUE, art. 19"},
{id:"ue3-043",t:"ue",q:"Qu'est devenu le Tribunal de la fonction publique de l'Union européenne ?",o:["Il a fusionné avec la Cour européenne des droits de l'homme","Il est devenu le Parquet européen","Il a été transformé en Médiateur européen","Il a été supprimé en 2016 et ses compétences ont été transférées au Tribunal"],a:3,e:"Créé en 2004, il jugeait les litiges entre l'Union et ses agents ; il a été dissous le 1er septembre 2016.",u:["https://fr.wikipedia.org/wiki/Tribunal_de_la_fonction_publique_de_l'Union_européenne"],s:"Banque UE"},
{id:"ue3-044",t:"ue",q:"À combien s'élève, en prix de 2018, le cadre financier pluriannuel 2021-2027 adopté en décembre 2020 ?",o:["Environ 500 Md€","Environ 750 Md€","Environ 1 074 Md€","Environ 3 000 Md€"],a:2,e:"Soit environ 1 211 Md€ en prix courants ; s'y ajoutent les 750 Md€ (prix 2018) de NextGenerationEU.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/budget-a-long-terme-de-l-ue-qu-est-ce-que-le-cadre-financier-pluriannuel-cfp/"],s:"Règlement (UE, Euratom) 2020/2093"},
{id:"ue3-045",t:"ue",q:"Comment se répartissaient les 750 Md€ (prix de 2018) de NextGenerationEU ?",o:["750 Md€ de prêts","750 Md€ de subventions","500 Md€ de subventions et 250 Md€ de prêts","390 Md€ de subventions et 360 Md€ de prêts"],a:3,e:"La proposition initiale de la Commission (mai 2020) prévoyait 500 Md€ de subventions ; le Conseil européen de juillet 2020 a retenu 390 Md€.",u:["https://fr.wikipedia.org/wiki/Plan_de_relance_européen_de_2020"],s:"Conseil européen, juillet 2020"},
{id:"ue3-046",t:"ue",q:"Quel instrument constitue l'essentiel de NextGenerationEU ?",o:["Le Fonds européen de développement régional","Le Fonds européen de la défense","La facilité pour la reprise et la résilience","Le Mécanisme européen de stabilité"],a:2,e:"672,5 Md€ en prix 2018 (312,5 Md€ de subventions et 360 Md€ de prêts), versés selon l'atteinte de jalons et de cibles fixés dans les plans nationaux.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/qu-est-ce-que-le-plan-de-relance-de-l-union-europeenne-infographie/"],s:"Règlement (UE) 2021/241"},
{id:"ue3-047",t:"ue",q:"Jusqu'à quelle date la Commission peut-elle effectuer les paiements au titre de la facilité pour la reprise et la résilience ?",o:["31 décembre 2023","31 décembre 2026","31 décembre 2030","31 décembre 2058"],a:1,e:"Les jalons et cibles devaient être atteints au plus tard le 31 août 2026 ; les paiements doivent intervenir au plus tard le 31 décembre 2026.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/qu-est-ce-que-le-plan-de-relance-de-l-union-europeenne-infographie/"],s:"Règlement (UE) 2021/241"},
{id:"ue3-048",t:"ue",q:"Au plus tard à quelle date l'emprunt contracté pour NextGenerationEU doit-il être remboursé ?",o:["2030","2040","2058","2100"],a:2,e:"La décision relative aux ressources propres de 2020 fixe l'échéance au 31 décembre 2058 ; ce remboursement pèse sur les prochains cadres financiers.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/budget-europeen-quelles-ressources-propres-pour-l-union-europeenne/"],s:"Décision (UE, Euratom) 2020/2053"},
{id:"ue3-049",t:"ue",q:"Qui emprunte sur les marchés financiers pour financer NextGenerationEU ?",o:["La Commission européenne, au nom de l'Union","La Banque centrale européenne","Chaque État membre pour sa propre part","Le Mécanisme européen de stabilité"],a:0,e:"Emprunt commun d'une ampleur inédite, autorisé par la décision relative aux ressources propres de 2020.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/qu-est-ce-que-le-plan-de-relance-de-l-union-europeenne-infographie/"],s:"Banque UE"},
{id:"ue3-050",t:"ue",q:"Quelle part minimale de chaque plan national pour la reprise et la résilience devait être consacrée aux objectifs climatiques ?",o:["10 %","20 %","37 %","50 %"],a:2,e:"Au moins 37 % pour le climat et 20 % pour la transition numérique.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/qu-est-ce-que-le-plan-de-relance-de-l-union-europeenne-infographie/"],s:"Règlement (UE) 2021/241"},
{id:"ue3-051",t:"ue",q:"Quel était le montant du plan France Relance présenté en septembre 2020 ?",o:["10 Md€","40 Md€","100 Md€","500 Md€"],a:2,e:"Environ 40 Md€ de ce plan ont été financés par l'Union via la facilité pour la reprise et la résilience.",u:["https://fr.wikipedia.org/wiki/Plan_de_relance_économique_de_la_France_de_2020-2022"],s:"Banque UE"},
{id:"ue3-052",t:"ue",q:"Sous quelle forme la France a-t-elle bénéficié de la facilité pour la reprise et la résilience ?",o:["Uniquement sous forme de prêts","Sous forme de garanties de la BEI","Sous forme d'achats de dette par la BCE","Uniquement sous forme de subventions"],a:3,e:"Le plan national de relance et de résilience français, approuvé en 2021, n'a pas mobilisé le volet prêts de la facilité.",u:["https://www.touteleurope.eu/economie-et-social/quel-est-le-montant-du-plan-de-relance-europeen-alloue-a-la-france/"],s:"Banque UE"},
{id:"ue3-053",t:"ue",q:"Comment la décision relative au système des ressources propres de l'Union est-elle adoptée (art. 311 TFUE) ?",o:["Par le Conseil à l'unanimité après consultation du Parlement européen, puis approbation par chaque État selon ses règles constitutionnelles","Par le Conseil à la majorité qualifiée, sans intervention des États","Par le Parlement européen seul","Par la Commission, après avis de la Cour des comptes"],a:0,e:"La décision de 2020 est entrée en vigueur le 1er juin 2021, avec effet au 1er janvier 2021, une fois approuvée par les 27 États.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/budget-europeen-quelles-ressources-propres-pour-l-union-europeenne/"],s:"TFUE, art. 311"},
{id:"ue3-054",t:"ue",q:"Quel plafond la décision de 2020 fixe-t-elle pour les ressources propres destinées aux crédits de paiement, hors relèvement temporaire lié à NextGenerationEU ?",o:["1,00 % du RNB de l'UE","1,40 % du RNB de l'UE","3 % du PIB de l'UE","5 % du RNB de l'UE"],a:1,e:"1,40 % pour les paiements (1,46 % pour les engagements), relevé temporairement de 0,6 point pour couvrir l'emprunt de NextGenerationEU.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/budget-europeen-quelles-ressources-propres-pour-l-union-europeenne/"],s:"Décision (UE, Euratom) 2020/2053"},
{id:"ue3-055",t:"ue",q:"Quel est le taux d'appel de la ressource propre fondée sur les déchets d'emballages plastiques non recyclés ?",o:["0,08 € par kilogramme","0,80 € par kilogramme","8 € par kilogramme","80 € par kilogramme"],a:1,e:"En vigueur depuis le 1er janvier 2021, avec une réduction forfaitaire pour les États dont le RNB par habitant est inférieur à la moyenne.",u:["https://www.touteleurope.eu/environnement/environnement-qu-est-ce-que-la-ressource-plastique-de-l-union-europeenne/"],s:"Décision (UE, Euratom) 2020/2053"},
{id:"ue3-056",t:"ue",q:"Quelle part des droits de douane perçus les États membres conservent-ils au titre des frais de perception depuis 2021 ?",o:["10 %","20 %","25 %","50 %"],a:2,e:"25 % depuis 2021, contre 20 % sur la période 2014-2020 ; le reste est versé au budget de l'Union.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/budget-europeen-quelles-ressources-propres-pour-l-union-europeenne/"],s:"Décision (UE, Euratom) 2020/2053"},
{id:"ue3-057",t:"ue",q:"Quelles ressources propres sont dites « traditionnelles » ?",o:["La ressource fondée sur le RNB","La ressource fondée sur la TVA","Les droits de douane perçus sur les importations en provenance des pays tiers","Les amendes infligées aux entreprises"],a:2,e:"Elles reviennent par nature à l'Union, puisque le tarif douanier est commun.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/budget-europeen-quelles-ressources-propres-pour-l-union-europeenne/"],s:"Banque UE"},
{id:"ue3-058",t:"ue",q:"En quelle année le financement des Communautés par contributions nationales a-t-il été remplacé par un système de ressources propres ?",o:["1957","1970","1988","2000"],a:1,e:"Décision du 21 avril 1970 ; la ressource fondée sur le PNB (aujourd'hui RNB) a été ajoutée en 1988 (paquet Delors I).",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/budget-europeen-quelles-ressources-propres-pour-l-union-europeenne/"],s:"Banque UE"},
{id:"ue3-059",t:"ue",q:"Pourquoi la ressource fondée sur le revenu national brut est-elle qualifiée de « ressource d'équilibre » ?",o:["Elle est versée à parts égales par chaque État","Elle sert à équilibrer les échanges commerciaux","Elle est remboursée aux États en fin d'année","Son taux d'appel est fixé chaque année pour couvrir les dépenses non financées par les autres recettes"],a:3,e:"Créée en 1988 (paquet Delors I), elle représente aujourd'hui la majeure partie des recettes du budget.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/budget-europeen-quelles-ressources-propres-pour-l-union-europeenne/"],s:"Banque UE"},
{id:"ue3-060",t:"ue",q:"Laquelle de ces recettes la Commission a-t-elle proposé, dès 2021, d'ajouter aux ressources propres de l'Union ?",o:["Un impôt européen sur le revenu des ménages","Une part de la contribution sociale généralisée","Une part des recettes du système d'échange de quotas d'émission (SEQE-UE)","Une taxe sur les pensions de retraite"],a:2,e:"Le paquet de décembre 2021 visait aussi le mécanisme d'ajustement carbone aux frontières et une part des bénéfices résiduels des multinationales ; la proposition de CFP 2028-2034 en ajoute d'autres.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/budget-europeen-quelles-ressources-propres-pour-l-union-europeenne/"],s:"Commission, décembre 2021"},
{id:"ue3-061",t:"ue",q:"Lors de quel Conseil européen le Royaume-Uni a-t-il obtenu en 1984 une correction de sa contribution, le « rabais britannique » ?",o:["Fontainebleau","Maastricht","Édimbourg","Copenhague"],a:0,e:"Margaret Thatcher dénonçait l'écart entre la contribution britannique et les retours, faibles au titre de la PAC.",u:["https://fr.wikipedia.org/wiki/Rabais_britannique"],s:"Conseil européen, 1984"},
{id:"ue3-062",t:"ue",q:"Quels États bénéficient de corrections forfaitaires de leur contribution fondée sur le RNB sur la période 2021-2027 ?",o:["La France, l'Italie et l'Espagne","La Pologne et la Hongrie","L'Irlande, le Luxembourg et Malte","L'Allemagne, l'Autriche, le Danemark, les Pays-Bas et la Suède"],a:3,e:"Ces « rabais » ont été maintenus et revalorisés après le Brexit, dans le compromis de juillet 2020 sur NextGenerationEU.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/budget-europeen-quels-pays-versent-plus-qu-ils-ne-recoivent/"],s:"Décision (UE, Euratom) 2020/2053"},
{id:"ue3-063",t:"ue",q:"La France est-elle bénéficiaire nette ou contributrice nette au budget de l'Union ?",o:["Contributrice nette : elle verse davantage qu'elle ne reçoit","Bénéficiaire nette grâce à la PAC","À l'équilibre exact chaque année","Elle ne contribue pas au budget de l'Union"],a:0,e:"Elle est, en montant, l'un des principaux contributeurs nets, tout en étant le premier bénéficiaire de la PAC.",u:["https://www.touteleurope.eu/economie-et-social/combien-la-france-verse-t-elle-a-l-union-europeenne/"],s:"Banque UE"},
{id:"ue3-064",t:"ue",q:"Selon l'article 314 TFUE, la Commission présente le projet de budget annuel au plus tard :",o:["Le 1er juillet","Le 1er septembre","Le 1er octobre","Le 31 décembre"],a:1,e:"Le Conseil adopte sa position et la transmet au Parlement au plus tard le 1er octobre. En pratique, la Commission présente son projet dès le début de l'été.",u:["https://european-union.europa.eu/institutions-law-budget/budget/how-eu-budget-adopted_fr"],s:"TFUE, art. 314"},
{id:"ue3-065",t:"ue",q:"En cas de désaccord entre le Parlement et le Conseil sur le budget annuel, que se passe-t-il ?",o:["Le Conseil européen tranche à l'unanimité","La Cour de justice fixe le budget","Un comité de conciliation est convoqué et dispose de 21 jours pour aboutir à un projet commun","La Commission adopte seule le budget"],a:2,e:"Faute d'accord, la Commission présente un nouveau projet de budget.",u:["https://european-union.europa.eu/institutions-law-budget/budget/how-eu-budget-adopted_fr"],s:"TFUE, art. 314"},
{id:"ue3-066",t:"ue",q:"Si le budget de l'Union n'est pas définitivement adopté au début de l'exercice, quel régime s'applique ?",o:["La fermeture des administrations européennes","Le régime des douzièmes provisoires","La reconduction automatique du double des crédits","L'adoption du budget par la Commission seule"],a:1,e:"Art. 315 TFUE : les dépenses peuvent être effectuées chaque mois dans la limite d'un douzième des crédits de l'exercice précédent.",u:["https://european-union.europa.eu/institutions-law-budget/budget/how-eu-budget-adopted_fr"],s:"TFUE, art. 315"},
{id:"ue3-067",t:"ue",q:"Comment appelle-t-on le mode d'exécution du budget dans lequel la Commission confie la gestion des fonds aux États membres, comme pour la PAC et la cohésion ?",o:["La gestion directe","La gestion indirecte","La comitologie","La gestion partagée"],a:3,e:"Elle concerne la majeure partie des dépenses ; la gestion indirecte passe par des organisations internationales, des agences ou des pays tiers.",u:["https://www.touteleurope.eu/l-europe-et-moi/les-modes-de-gestion-des-programmes/"],s:"Règlement financier"},
{id:"ue3-068",t:"ue",q:"Lequel de ces principes ne figure pas parmi les principes budgétaires de l'Union ?",o:["L'annualité","L'affectation de chaque recette à une dépense déterminée","L'équilibre","L'unité de compte (l'euro)"],a:1,e:"Le principe d'universalité impose au contraire que l'ensemble des recettes couvre l'ensemble des dépenses, sauf exceptions (recettes affectées).",u:["https://european-union.europa.eu/institutions-law-budget/budget_fr"],s:"Règlement financier"},
{id:"ue3-069",t:"ue",q:"Que fixe le cadre financier pluriannuel pour chaque catégorie de dépenses ?",o:["Le montant exact du budget de chaque année","Les taux de TVA nationaux","Des plafonds annuels de crédits d'engagement","La contribution de chaque État membre"],a:2,e:"Art. 312 TFUE : il fixe aussi un plafond annuel des crédits de paiement ; le budget annuel doit respecter ces plafonds.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/budget-a-long-terme-de-l-ue-qu-est-ce-que-le-cadre-financier-pluriannuel-cfp/"],s:"TFUE, art. 312"},
{id:"ue3-070",t:"ue",q:"Pour quelle durée minimale le cadre financier pluriannuel est-il établi selon l'article 312 TFUE ?",o:["Trois ans","Cinq ans","Sept ans","Dix ans"],a:1,e:"En pratique, les cadres récents couvrent sept ans (2014-2020, 2021-2027), comme celui proposé pour 2028-2034.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/budget-a-long-terme-de-l-ue-qu-est-ce-que-le-cadre-financier-pluriannuel-cfp/"],s:"TFUE, art. 312"},
{id:"ue3-071",t:"ue",q:"Combien de rubriques de dépenses le cadre financier pluriannuel 2021-2027 compte-t-il ?",o:["Trois","Cinq","Sept","Douze"],a:2,e:"Marché unique, innovation et numérique ; cohésion, résilience et valeurs ; ressources naturelles et environnement ; migration et gestion des frontières ; sécurité et défense ; voisinage et monde ; administration publique européenne.",u:["https://fr.wikipedia.org/wiki/Budget_de_l'Union_européenne"],s:"Règlement (UE, Euratom) 2020/2093"},
{id:"ue3-072",t:"ue",q:"Quel instrument de 50 Md€ pour 2024-2027 a été créé lors de la révision du cadre financier pluriannuel en février 2024 ?",o:["La facilité pour l'Ukraine","Le Mécanisme européen de stabilité","L'instrument SURE","Le programme InvestEU"],a:0,e:"Elle combine environ 17 Md€ de subventions et 33 Md€ de prêts pour soutenir la reconstruction et la modernisation de l'Ukraine.",u:["https://european-union.europa.eu/priorities-and-actions/eu-support-ukraine_fr"],s:"Révision du CFP, février 2024"},
{id:"ue3-073",t:"ue",q:"Quel instrument européen créé en 2020 a accordé jusqu'à 100 Md€ de prêts aux États pour financer notamment le chômage partiel ?",o:["REPowerEU","InvestEU","Horizon Europe","SURE"],a:3,e:"Instrument de soutien temporaire à l'atténuation des risques de chômage en situation d'urgence, fondé sur l'article 122 TFUE et financé par des emprunts de la Commission.",s:"Règlement (UE) 2020/672"},
{id:"ue3-074",t:"ue",q:"Quel règlement de décembre 2020 permet de suspendre des financements de l'Union à un État dont les violations des principes de l'État de droit menacent la bonne gestion financière du budget ?",o:["Le règlement financier","Le règlement portant dispositions communes aux fonds","Le règlement relatif à un régime général de conditionnalité pour la protection du budget de l'Union","Le règlement établissant l'instrument SURE"],a:2,e:"Règlement (UE, Euratom) 2020/2092, applicable depuis le 1er janvier 2021.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/comment-l-ue-conditionne-t-elle-les-fonds-europeens-au-respect-de-l-etat-de-droit/"],s:"Règlement (UE, Euratom) 2020/2092"},
{id:"ue3-075",t:"ue",q:"Qui adopte les mesures prévues par le mécanisme de conditionnalité liée à l'État de droit ?",o:["Le Conseil européen, à l'unanimité","Le Conseil, à la majorité qualifiée, sur proposition de la Commission","Le Parlement européen seul","La Cour de justice, sur saisine d'un État"],a:1,e:"La majorité qualifiée évite qu'un seul État puisse bloquer les mesures.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/comment-l-ue-conditionne-t-elle-les-fonds-europeens-au-respect-de-l-etat-de-droit/"],s:"Règlement (UE, Euratom) 2020/2092"},
{id:"ue3-076",t:"ue",q:"Contre quel État le mécanisme de conditionnalité liée à l'État de droit a-t-il été appliqué pour la première fois, en décembre 2022 ?",o:["La Hongrie","La Pologne","La Roumanie","La Slovaquie"],a:0,e:"Le Conseil a suspendu environ 6,3 Md€ d'engagements au titre de programmes de la politique de cohésion.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/etat-de-droit-chronologie-du-conflit-entre-l-union-europeenne-et-la-hongrie/"],s:"Conseil, 15 décembre 2022"},
{id:"ue3-077",t:"ue",q:"Qu'a décidé la Cour de justice dans ses arrêts du 16 février 2022 relatifs au règlement de conditionnalité ?",o:["Elle a annulé le règlement","Elle a exclu la Hongrie de l'Union","Elle a condamné la Commission pour carence","Elle a rejeté les recours en annulation de la Hongrie et de la Pologne"],a:3,e:"La Cour juge que le respect des valeurs de l'article 2 TUE conditionne la jouissance des droits découlant des traités et que le budget peut en être un instrument de protection.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/comment-l-ue-conditionne-t-elle-les-fonds-europeens-au-respect-de-l-etat-de-droit/"],s:"CJUE, 16 février 2022"},
{id:"ue3-078",t:"ue",q:"Quand la Commission a-t-elle présenté sa proposition de cadre financier pluriannuel pour 2028-2034 ?",o:["Décembre 2020","Mars 2023","Juillet 2025","Janvier 2028"],a:2,e:"Le 16 juillet 2025. Le règlement fixant le cadre est adopté par le Conseil à l'unanimité, après approbation du Parlement européen (art. 312 TFUE).",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/budget-de-l-union-europeenne-la-commission-devoile-un-cadre-financier-de-2-000-milliards-d-euros-pour-la-periode-2028-2034/"],s:"Commission, 16 juillet 2025",act:1},
{id:"ue3-079",t:"ue",q:"Quelle innovation majeure la proposition de la Commission pour le cadre financier 2028-2034 prévoit-elle ?",o:["Des plans de partenariat nationaux et régionaux regroupant notamment les crédits de la cohésion et de la PAC","La suppression de la ressource fondée sur le RNB","L'autorisation de voter le budget annuel en déficit","La suppression du rôle du Parlement européen dans la procédure budgétaire"],a:0,e:"Elle prévoit aussi un Fonds européen pour la compétitivité et de nouvelles ressources propres.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/budget-de-l-union-europeenne-la-commission-devoile-un-cadre-financier-de-2-000-milliards-d-euros-pour-la-periode-2028-2034/"],s:"Commission, juillet 2025",act:1},
{id:"ue3-080",t:"ue",q:"Qui sont les actionnaires de la Banque européenne d'investissement (BEI) ?",o:["Les banques centrales de la zone euro","Les banques commerciales européennes","Les États membres de l'Union","La Commission européenne"],a:2,e:"Créée par le traité de Rome (1957), installée à Luxembourg, elle emprunte sur les marchés pour financer des projets conformes aux objectifs de l'Union.",u:["https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/european-investment-bank-eib_fr"],s:"TFUE, art. 308"},
{id:"ue3-081",t:"ue",q:"Quel organe consultatif de l'Union représente les collectivités régionales et locales ?",o:["Le Comité économique et social européen","Le Comité européen des régions","Le Conseil de l'Europe","Le Coreper"],a:1,e:"Créé par le traité de Maastricht et installé en 1994, il est obligatoirement consulté dans certains domaines (cohésion, transports, environnement…).",u:["https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/european-committee-regions-cor_fr"],s:"TFUE, art. 305"},
{id:"ue3-082",t:"ue",q:"Quel article du TFUE définit le marché intérieur comme un espace sans frontières intérieures où est assurée la libre circulation des marchandises, des personnes, des services et des capitaux ?",o:["Article 101","Article 20","Article 288","Article 26"],a:3,e:"L'Acte unique européen avait fixé son achèvement au 31 décembre 1992.",u:["https://www.touteleurope.eu/economie-et-social/le-marche-unique/"],s:"TFUE, art. 26"},
{id:"ue3-083",t:"ue",q:"Quel article du TFUE permet aux États de justifier des restrictions aux échanges de marchandises pour des raisons de moralité publique, d'ordre public, de sécurité publique ou de protection de la santé ?",o:["Article 34","Article 36","Article 107","Article 258"],a:1,e:"Ces restrictions ne doivent constituer ni une discrimination arbitraire ni une restriction déguisée. L'article 34 pose l'interdiction de principe.",u:["https://www.touteleurope.eu/economie-et-social/la-libre-circulation-des-marchandises/"],s:"TFUE, art. 36"},
{id:"ue3-084",t:"ue",q:"Qu'interdit l'article 110 TFUE ?",o:["Toute taxe sur la valeur ajoutée","Les droits d'accise sur les alcools","Les impositions intérieures frappant les produits des autres États membres plus lourdement que les produits nationaux similaires","L'impôt sur les sociétés"],a:2,e:"Il complète l'interdiction des droits de douane et des taxes d'effet équivalent entre États membres (art. 28 et 30 TFUE).",u:["https://www.touteleurope.eu/economie-et-social/la-libre-circulation-des-marchandises/"],s:"TFUE, art. 110"},
{id:"ue3-085",t:"ue",q:"À quels emplois la libre circulation des travailleurs ne s'applique-t-elle pas (art. 45 § 4 TFUE) ?",o:["Aux emplois dans l'administration publique impliquant l'exercice de la puissance publique","Aux emplois du secteur privé","Aux emplois à temps partiel","Aux emplois saisonniers agricoles"],a:0,e:"La Cour de justice interprète strictement cette exception : la plupart des emplois publics (enseignement, santé…) sont ouverts aux ressortissants de l'Union.",u:["https://www.touteleurope.eu/economie-et-social/la-libre-circulation-des-personnes/"],s:"TFUE, art. 45"},
{id:"ue3-086",t:"ue",q:"Quelle liberté permet à un professionnel de s'installer de façon stable et continue dans un autre État membre pour y exercer son activité ?",o:["La libre prestation de services","La libre circulation des capitaux","La libre circulation des marchandises","La liberté d'établissement"],a:3,e:"Art. 49 TFUE ; la libre prestation de services (art. 56) couvre une activité temporaire exercée sans installation dans l'État d'accueil.",u:["https://www.touteleurope.eu/economie-et-social/la-libre-circulation-des-services-et-la-liberte-d-etablissement/"],s:"TFUE, art. 49"},
{id:"ue3-087",t:"ue",q:"Quelle directive de 2006, dite « Bolkestein », facilite la liberté d'établissement et la libre prestation de services ?",o:["La directive sur le détachement de travailleurs","La directive TVA","La directive « services » 2006/123/CE","La directive sur le temps de travail"],a:2,e:"Le principe du « pays d'origine » de la proposition initiale (2004) a été abandonné dans le texte adopté.",u:["https://www.touteleurope.eu/economie-et-social/la-libre-circulation-des-services-et-la-liberte-d-etablissement/"],s:"Directive 2006/123/CE"},
{id:"ue3-088",t:"ue",q:"Selon la directive sur le détachement de travailleurs révisée en 2018, au-delà de quelle durée l'essentiel du droit du travail du pays d'accueil s'applique-t-il au travailleur détaché ?",o:["Six mois","Douze mois, prolongeables à dix-huit","Vingt-quatre mois","Cinq ans"],a:1,e:"La révision consacre le principe « à travail égal, salaire égal sur un même lieu de travail » : la rémunération du pays d'accueil s'applique dès le premier jour.",u:["https://fr.wikipedia.org/wiki/Travailleur_détaché"],s:"Directive (UE) 2018/957"},
{id:"ue3-089",t:"ue",q:"Quelle est la particularité de la libre circulation des capitaux (art. 63 TFUE) ?",o:["Elle ne s'applique que dans la zone euro","Elle s'applique aussi aux mouvements entre les États membres et les pays tiers","Elle ne concerne que les personnes physiques","Elle ne concerne que les investissements immobiliers"],a:1,e:"Des restrictions restent possibles, notamment pour des raisons fiscales ou de sécurité publique (art. 65 TFUE).",u:["https://www.touteleurope.eu/economie-et-social/la-libre-circulation-des-capitaux-et-des-services-financiers/"],s:"TFUE, art. 63"},
{id:"ue3-090",t:"ue",q:"Selon l'article 88-3 de la Constitution, un citoyen de l'Union élu conseiller municipal en France ne peut pas :",o:["Exercer les fonctions de maire ou d'adjoint, ni participer à l'élection des sénateurs","Voter les délibérations du conseil municipal","Siéger dans les commissions municipales","Voter le budget de la commune"],a:0,e:"Le droit de vote et d'éligibilité aux municipales des ressortissants de l'Union a été introduit par la révision constitutionnelle de 1992 liée au traité de Maastricht.",s:"Constitution, art. 88-3"},
{id:"ue3-091",t:"ue",q:"Lequel de ces droits n'est pas attaché à la citoyenneté de l'Union ?",o:["Le droit de pétition devant le Parlement européen","Le droit de saisir le Médiateur européen","Le droit de s'adresser aux institutions dans l'une des langues des traités","Le droit de vote aux élections législatives de l'État de résidence"],a:3,e:"Art. 20 TFUE : libre circulation et séjour, vote et éligibilité aux municipales et européennes, protection consulaire, pétition, Médiateur, correspondance dans sa langue.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/petition-initiative-citoyenne-mediateur-europeen-3-outils-pour-agir-en-tant-que-citoyen-au-niveau-europeen/"],s:"TFUE, art. 20"},
{id:"ue3-092",t:"ue",q:"Après combien d'années de séjour légal ininterrompu un citoyen de l'Union acquiert-il un droit de séjour permanent dans l'État d'accueil ?",o:["Deux ans","Cinq ans","Dix ans","Quinze ans"],a:1,e:"Directive 2004/38/CE ; le droit de séjour permanent n'est plus soumis à conditions de ressources.",u:["https://www.touteleurope.eu/economie-et-social/la-libre-circulation-des-personnes/"],s:"Directive 2004/38/CE"},
{id:"ue3-093",t:"ue",q:"Pendant combien de temps un citoyen de l'Union peut-il séjourner dans un autre État membre avec une simple carte d'identité ou un passeport en cours de validité, sans autre condition ?",o:["Un mois","Trois mois","Un an","Cinq ans"],a:1,e:"Au-delà, il doit être travailleur, étudiant, ou disposer de ressources suffisantes et d'une assurance maladie (directive 2004/38/CE).",u:["https://www.touteleurope.eu/economie-et-social/la-libre-circulation-des-personnes/"],s:"Directive 2004/38/CE"},
{id:"ue3-094",t:"ue",q:"Quel article du TFUE interdit les ententes entre entreprises qui ont pour objet ou pour effet de restreindre la concurrence ?",o:["Article 101","Article 102","Article 107","Article 34"],a:0,e:"Des exemptions sont possibles si l'accord contribue au progrès économique en réservant aux utilisateurs une partie équitable du profit (art. 101 § 3).",u:["https://european-union.europa.eu/priorities-and-actions/actions-topic/competition_fr"],s:"TFUE, art. 101"},
{id:"ue3-095",t:"ue",q:"Que prohibe l'article 102 TFUE ?",o:["La détention d'une position dominante","Toute concentration d'entreprises","L'exploitation abusive d'une position dominante","Les aides accordées par les États"],a:2,e:"Détenir une position dominante n'est pas interdit en soi ; seul son abus l'est (prix prédateurs, refus d'accès, ventes liées…).",u:["https://european-union.europa.eu/priorities-and-actions/actions-topic/competition_fr"],s:"TFUE, art. 102"},
{id:"ue3-096",t:"ue",q:"Qui contrôle les concentrations d'entreprises de dimension européenne ?",o:["La Banque centrale européenne","La Commission européenne","L'Autorité de la concurrence française","Le Conseil de l'UE"],a:1,e:"Règlement (CE) n° 139/2004 : les opérations dépassant certains seuils de chiffre d'affaires doivent être notifiées à la Commission avant leur réalisation.",u:["https://european-union.europa.eu/priorities-and-actions/actions-topic/competition_fr"],s:"Règlement (CE) n° 139/2004"},
{id:"ue3-097",t:"ue",q:"Quel projet de fusion la Commission européenne a-t-elle interdit en février 2019 ?",o:["Fiat Chrysler-Renault","Air France-KLM","Peugeot-Fiat Chrysler","Alstom-Siemens"],a:3,e:"Elle a estimé que l'opération aurait nui à la concurrence sur les marchés de la signalisation ferroviaire et des trains à très grande vitesse.",s:"Commission, 6 février 2019"},
{id:"ue3-098",t:"ue",q:"Selon l'article 108 TFUE, un projet d'aide d'État doit en principe être :",o:["Notifié au Parlement européen après son versement","Notifié à la Commission et ne pas être mis à exécution avant sa décision","Approuvé par la Cour de justice","Autorisé par le Conseil européen à l'unanimité"],a:1,e:"Une aide versée sans notification est illégale ; si elle est en outre incompatible avec le marché intérieur, elle doit être récupérée avec intérêts.",u:["https://www.touteleurope.eu/economie-et-social/podcast-pourquoi-l-union-europeenne-bloque-certaines-aides-publiques/"],s:"TFUE, art. 108"},
{id:"ue3-099",t:"ue",q:"Lesquelles de ces aides sont compatibles de plein droit avec le marché intérieur (art. 107 § 2 TFUE) ?",o:["Les aides au fonctionnement des entreprises en difficulté","Les aides favorisant les exportations vers d'autres États membres","Les aides destinées à remédier aux dommages causés par les calamités naturelles","Toutes les aides inférieures à 1 M€"],a:2,e:"Le § 2 vise aussi les aides à caractère social aux consommateurs individuels ; le § 3 énumère des aides qui peuvent être déclarées compatibles (régionales, projets d'intérêt européen…).",u:["https://european-union.europa.eu/priorities-and-actions/actions-topic/competition_fr"],s:"TFUE, art. 107"},
{id:"ue3-100",t:"ue",q:"Depuis 2024, quel est le plafond des aides dites de minimis qu'une entreprise peut recevoir sur trois ans sans notification à la Commission ?",o:["100 000 €","200 000 €","300 000 €","1 000 000 €"],a:2,e:"Règlement (UE) 2023/2831, applicable depuis le 1er janvier 2024 ; le plafond était auparavant de 200 000 €.",s:"Règlement (UE) 2023/2831"},
{id:"ue3-101",t:"ue",q:"Par un arrêt du 10 septembre 2024, la Cour de justice a confirmé que l'Irlande devait récupérer environ 13 Md€ d'aide d'État illégale accordée sous forme d'avantages fiscaux à :",o:["Apple","Google","Amazon","Starbucks"],a:0,e:"La Cour a annulé l'arrêt du Tribunal de 2020 et confirmé la décision de la Commission de 2016.",x:"Des rescrits fiscaux peuvent constituer des aides d'État s'ils accordent un avantage sélectif.",s:"CJUE, 10 septembre 2024"},
{id:"ue3-102",t:"ue",q:"Quel est le plafond des amendes que la Commission peut infliger pour une entente ou un abus de position dominante ?",o:["1 % du chiffre d'affaires mondial","4 % du chiffre d'affaires mondial","10 % du chiffre d'affaires mondial total","20 M€"],a:2,e:"Règlement (CE) n° 1/2003, art. 23.",u:["https://european-union.europa.eu/priorities-and-actions/actions-topic/competition_fr"],s:"Règlement (CE) n° 1/2003"},
{id:"ue3-103",t:"ue",q:"Qu'est-ce qui distingue une union douanière d'une simple zone de libre-échange ?",o:["La suppression des droits de douane entre ses membres","L'adoption d'une monnaie unique","La libre circulation des travailleurs","L'adoption d'un tarif douanier extérieur commun"],a:3,e:"L'union douanière de la CEE, achevée le 1er juillet 1968, a supprimé les droits internes et instauré un tarif extérieur commun.",u:["https://european-union.europa.eu/priorities-and-actions/actions-topic/customs_fr"],s:"TFUE, art. 28"},
{id:"ue3-104",t:"ue",q:"Quel texte fixe les règles douanières communes appliquées depuis le 1er mai 2016 ?",o:["Le code général des impôts","La directive TVA de 2006","Le code des douanes de l'Union (règlement de 2013)","Le règlement général d'exemption par catégorie"],a:2,e:"Règlement (UE) n° 952/2013 ; en France, la DGDDI applique ce droit commun.",u:["https://european-union.europa.eu/priorities-and-actions/actions-topic/customs_fr"],s:"Règlement (UE) n° 952/2013"},
{id:"ue3-105",t:"ue",q:"Quel pays tiers forme une union douanière avec l'Union européenne depuis le 31 décembre 1995 ?",o:["La Norvège","La Turquie","La Suisse","Le Royaume-Uni"],a:1,e:"Décision n° 1/95 du conseil d'association CE-Turquie ; elle couvre surtout les produits industriels. La Norvège participe à l'Espace économique européen et la Suisse est liée par des accords bilatéraux.",u:["https://fr.wikipedia.org/wiki/Union_douanière_entre_l'Union_européenne_et_la_Turquie"],s:"Banque UE"},
{id:"ue3-106",t:"ue",q:"Depuis le traité de Lisbonne, l'approbation de quelle institution est nécessaire pour conclure un accord commercial de l'Union ?",o:["Le Parlement européen","Le Comité économique et social européen","La Banque centrale européenne","La Cour des comptes européenne"],a:0,e:"Le Parlement a par exemple rejeté l'accord commercial anti-contrefaçon (ACTA) en 2012.",u:["https://european-union.europa.eu/priorities-and-actions/actions-topic/trade_fr"],s:"TFUE, art. 218"},
{id:"ue3-107",t:"ue",q:"Pourquoi l'accord avec le Canada (CETA) doit-il, en plus de sa conclusion par l'Union, être ratifié par chaque État membre ?",o:["La politique commerciale est une compétence nationale","Le Canada l'a exigé","Il crée une union monétaire","C'est un accord mixte, qui comporte des dispositions relevant de compétences nationales"],a:3,e:"Il est appliqué à titre provisoire, pour sa partie relevant de l'Union, depuis le 21 septembre 2017.",u:["https://www.touteleurope.eu/economie-et-social/qu-est-ce-que-le-ceta/"],s:"Banque UE"},
{id:"ue3-108",t:"ue",q:"Comment l'Union européenne est-elle représentée à l'Organisation mondiale du commerce ?",o:["Elle en est membre à part entière, aux côtés de ses États membres, et y est représentée par la Commission","Elle n'y a qu'un statut d'observateur","Par l'État qui assure la présidence tournante du Conseil","Elle n'y est pas représentée"],a:0,e:"L'OMC, créée en 1995 et installée à Genève, a succédé au GATT de 1947.",u:["https://european-union.europa.eu/priorities-and-actions/actions-topic/trade_fr"],s:"Banque UE"},
{id:"ue3-109",t:"ue",q:"Quel instrument adopté en 2023 permet à l'Union de riposter aux pressions économiques exercées par un pays tiers pour influencer ses choix politiques ?",o:["Le mécanisme d'ajustement carbone aux frontières","Le règlement sur les services numériques","L'instrument anti-coercition","Le programme InvestEU"],a:2,e:"Règlement (UE) 2023/2675 : droits de douane, restrictions d'accès aux marchés publics ou aux investissements… en dernier recours.",u:["https://www.touteleurope.eu/l-ue-dans-le-monde/droits-de-douane-qu-est-ce-que-l-instrument-anti-coercition-europeen-demande-par-emmanuel-macron-pour-contrer-donald-trump/"],s:"Règlement (UE) 2023/2675"},
{id:"ue3-110",t:"ue",q:"Quel instrument de défense commerciale permet de taxer des importations vendues dans l'Union à un prix inférieur à leur valeur normale ?",o:["Les droits d'accise","Les droits antidumping","La TVA à l'importation","Le mécanisme d'ajustement carbone aux frontières"],a:1,e:"Les autres instruments sont les droits compensateurs (contre les subventions) et les mesures de sauvegarde.",u:["https://www.touteleurope.eu/l-ue-dans-le-monde/defense-commerciale-les-instruments-europeens/"],s:"Banque UE"},
{id:"ue3-111",t:"ue",q:"Que prévoit l'initiative européenne « Tout sauf les armes » (2001) ?",o:["Une aide militaire aux pays partenaires","L'interdiction des exportations d'armes européennes","Une exonération de TVA pour les produits importés","Un accès au marché de l'Union sans droits de douane ni contingents pour tous les produits des pays les moins avancés, sauf les armes et munitions"],a:3,e:"Elle relève du système de préférences généralisées (SPG) de l'Union.",u:["https://fr.wikipedia.org/wiki/Tout_sauf_les_armes"],s:"Banque UE"},
{id:"ue3-112",t:"ue",q:"Lequel de ces objectifs n'est pas assigné à la PAC par l'article 39 TFUE ?",o:["Accroître la productivité de l'agriculture","Garantir l'autosuffisance alimentaire de chaque État membre","Assurer un niveau de vie équitable à la population agricole","Stabiliser les marchés"],a:1,e:"Art. 39 : productivité, niveau de vie équitable, stabilisation des marchés, sécurité des approvisionnements et prix raisonnables pour les consommateurs.",u:["https://www.touteleurope.eu/agriculture-et-peche/qu-est-ce-que-la-pac/"],s:"TFUE, art. 39"},
{id:"ue3-113",t:"ue",q:"Quel fonds finance le second pilier de la PAC, consacré au développement rural ?",o:["Le FEAGA","Le FEDER","Le FEADER","Le FSE+"],a:2,e:"Fonds européen agricole pour le développement rural, cofinancé par les États ; le premier pilier est financé par le FEAGA.",u:["https://www.touteleurope.eu/l-europe-et-moi/le-fonds-europeen-agricole-pour-le-developpement-rural-feader/"],s:"Banque UE"},
{id:"ue3-114",t:"ue",q:"Que finance le premier pilier de la PAC (FEAGA) ?",o:["Les paiements directs aux agriculteurs et les mesures de soutien des marchés","Le développement rural","Les infrastructures régionales","La formation professionnelle des chômeurs"],a:0,e:"Il représente la plus grande part des crédits de la PAC et n'est pas cofinancé par les États.",u:["https://www.touteleurope.eu/l-europe-et-moi/le-fonds-europeen-agricole-de-garantie-feaga/"],s:"Banque UE"},
{id:"ue3-115",t:"ue",q:"Quelle réforme de la PAC de 1992 a remplacé une partie du soutien par les prix par des aides directes aux agriculteurs ?",o:["Le plan Mansholt","Le bilan de santé","La réforme Fischler","La réforme MacSharry"],a:3,e:"Baisse des prix garantis compensée par des aides à l'hectare ou à la tête de bétail, assortie d'un gel obligatoire d'une partie des terres arables (jachère).",u:["https://www.touteleurope.eu/histoire/histoire-de-la-politique-agricole-commune/"],s:"Banque UE"},
{id:"ue3-116",t:"ue",q:"En quelle année ont pris fin les quotas laitiers instaurés en 1984 ?",o:["1992","2003","2015","2023"],a:2,e:"La dernière campagne s'est achevée le 31 mars 2015.",u:["https://www.touteleurope.eu/histoire/histoire-de-la-politique-agricole-commune/"],s:"Banque UE"},
{id:"ue3-117",t:"ue",q:"Quel est le principe du « découplage » introduit par la réforme de la PAC de 2003 ?",o:["La séparation de la PAC et de la politique de la pêche","La possibilité pour un État de sortir de la PAC","Les aides directes ne dépendent plus du volume de production","Le transfert de la PAC aux régions"],a:2,e:"Réforme Fischler : paiement unique par exploitation, soumis au respect de normes (environnement, bien-être animal…).",u:["https://www.touteleurope.eu/histoire/histoire-de-la-politique-agricole-commune/"],s:"Banque UE"},
{id:"ue3-118",t:"ue",q:"Depuis le 1er janvier 2023, comment chaque État membre met-il en œuvre la PAC ?",o:["Par un traité bilatéral avec la Commission","Au moyen d'un plan stratégique national approuvé par la Commission","Par la transposition d'une directive annuelle","Par un budget annexe voté par le Parlement européen"],a:1,e:"La PAC 2023-2027 laisse plus de latitude aux États, qui choisissent leurs interventions au service d'objectifs communs.",u:["https://www.touteleurope.eu/agriculture-et-peche/qu-est-ce-que-la-pac/"],s:"Règlement (UE) 2021/2115"},
{id:"ue3-119",t:"ue",q:"Quelle part minimale des paiements directs le règlement (UE) 2021/2115 réserve-t-il aux éco-régimes pour la PAC 2023-2027 ?",o:["5 %","25 %","50 %","75 %"],a:1,e:"Les éco-régimes rémunèrent des pratiques favorables au climat et à l'environnement, au-delà de la conditionnalité obligatoire.",u:["https://www.touteleurope.eu/agriculture-et-peche/qu-est-ce-que-la-pac/"],s:"Règlement (UE) 2021/2115"},
{id:"ue3-120",t:"ue",q:"Quelle part approximative du cadre financier 2021-2027 la PAC représente-t-elle ?",o:["Environ 5 %","Environ 15 %","Environ un tiers","Environ 70 %"],a:2,e:"Elle reste avec la cohésion l'un des deux premiers postes ; dans les années 1980, elle absorbait plus de la moitié du budget communautaire.",u:["https://www.touteleurope.eu/agriculture-et-peche/budget-de-l-ue-a-qui-profite-la-pac/"],s:"Banque UE"},
{id:"ue3-121",t:"ue",q:"Quel État membre est le premier bénéficiaire des fonds de la PAC ?",o:["La France","L'Allemagne","La Pologne","L'Italie"],a:0,e:"Environ 9 Md€ par an, principalement au titre des paiements directs.",u:["https://www.touteleurope.eu/agriculture-et-peche/budget-de-l-ue-a-qui-profite-la-pac/"],s:"Banque UE"},
{id:"ue3-122",t:"ue",q:"Quel est l'objectif de la politique de cohésion selon l'article 174 TFUE ?",o:["Garantir un revenu minimal à chaque citoyen","Stabiliser les prix agricoles","Harmoniser les impôts locaux","Réduire l'écart entre les niveaux de développement des régions et le retard des régions les moins favorisées"],a:3,e:"Une attention particulière va aux zones rurales, aux zones en transition industrielle et aux régions souffrant de handicaps naturels ou démographiques.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/qu-est-ce-que-la-politique-de-cohesion-de-l-union-europeenne-2/"],s:"TFUE, art. 174"},
{id:"ue3-123",t:"ue",q:"Quels États sont éligibles au Fonds de cohésion ?",o:["Ceux dont le RNB par habitant est inférieur à 90 % de la moyenne de l'Union","Tous les États de la zone euro","Ceux dont le taux de chômage dépasse 10 %","Les seuls États ayant adhéré après 2004"],a:0,e:"La France n'y est pas éligible.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/qu-est-ce-que-la-politique-de-cohesion-de-l-union-europeenne-2/"],s:"TFUE, art. 177"},
{id:"ue3-124",t:"ue",q:"Que finance le Fonds de cohésion ?",o:["Les paiements directs aux agriculteurs","Le chômage partiel","Des projets dans les domaines de l'environnement et des réseaux transeuropéens de transport","Les retraites des fonctionnaires européens"],a:2,e:"Créé par le traité de Maastricht pour aider les États les moins prospères, notamment à préparer l'union économique et monétaire.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/qu-est-ce-que-la-politique-de-cohesion-de-l-union-europeenne-2/"],s:"TFUE, art. 177"},
{id:"ue3-125",t:"ue",q:"Pour la période 2021-2027, une région est dite « moins développée » lorsque son PIB par habitant est inférieur à :",o:["50 % de la moyenne de l'UE","75 % de la moyenne de l'UE","90 % de la moyenne de l'UE","100 % de la moyenne de l'UE"],a:1,e:"Régions en transition : de 75 % à 100 % ; régions plus développées : au-delà de 100 %.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/qu-est-ce-que-la-politique-de-cohesion-de-l-union-europeenne-2/"],s:"Règlement (UE) 2021/1060"},
{id:"ue3-126",t:"ue",q:"Quel fonds de la politique de cohésion soutient l'emploi, l'éducation et l'inclusion sociale sur la période 2021-2027 ?",o:["Le FEDER","Le FSE+","Le FEAMPA","Le FEAGA"],a:1,e:"Le Fonds social européen plus regroupe l'ancien FSE, le Fonds européen d'aide aux plus démunis et l'initiative pour l'emploi des jeunes.",u:["https://www.touteleurope.eu/l-europe-en-region/le-fonds-social-europeen-fse/"],s:"Règlement (UE) 2021/1057"},
{id:"ue3-127",t:"ue",q:"À quoi sert le Fonds pour une transition juste (FTJ) ?",o:["Financer les retraites agricoles","Indemniser les victimes d'erreurs judiciaires","Financer l'aide militaire à l'Ukraine","Accompagner les territoires les plus touchés par la transition vers la neutralité climatique"],a:3,e:"Il soutient notamment les régions dépendantes du charbon ou d'industries très émettrices (reconversion, formation, diversification).",u:["https://www.touteleurope.eu/l-europe-et-moi/le-fonds-pour-une-transition-juste-ftj/"],s:"Règlement (UE) 2021/1056"},
{id:"ue3-128",t:"ue",q:"Quel programme de la politique de cohésion finance la coopération transfrontalière, transnationale et interrégionale ?",o:["Erasmus+","Interreg","Horizon Europe","LIFE"],a:1,e:"Il relève de l'objectif de coopération territoriale européenne, financé par le FEDER.",u:["https://www.touteleurope.eu/l-europe-et-moi/la-cooperation-territoriale-europeenne/"],s:"Banque UE"},
{id:"ue3-129",t:"ue",q:"Selon les critères de convergence, le taux d'intérêt nominal à long terme d'un État candidat à l'euro ne doit pas dépasser de plus de :",o:["0,5 point","1,5 point","2 points","3 points"],a:2,e:"2 points celui des trois États membres présentant les meilleurs résultats en matière de stabilité des prix.",u:["https://www.touteleurope.eu/histoire/histoire-de-l-union-economique-et-monetaire-et-de-l-euro/"],s:"Protocole n° 13"},
{id:"ue3-130",t:"ue",q:"Selon les critères de convergence, le taux d'inflation d'un État candidat à l'euro ne doit pas dépasser de plus de :",o:["1 point","1,5 point","2,5 points","3 points"],a:1,e:"1,5 point la moyenne des trois États membres présentant les meilleurs résultats en matière de stabilité des prix.",u:["https://www.touteleurope.eu/histoire/histoire-de-l-union-economique-et-monetaire-et-de-l-euro/"],s:"Protocole n° 13"},
{id:"ue3-131",t:"ue",q:"Quelles valeurs de référence le protocole sur la procédure concernant les déficits excessifs fixe-t-il ?",o:["1 % du PIB pour le déficit et 100 % pour la dette","5 % du PIB pour le déficit et 90 % pour la dette","3 % du PIB pour le déficit public et 60 % du PIB pour la dette publique","0,5 % du PIB pour le déficit et 120 % pour la dette"],a:2,e:"Protocole n° 12 annexé aux traités ; ces seuils sont aussi des critères de convergence pour l'adoption de l'euro.",u:["https://www.touteleurope.eu/economie-et-social/qu-est-ce-que-le-pacte-de-stabilite-et-de-croissance/"],s:"Protocole n° 12"},
{id:"ue3-132",t:"ue",q:"Que prévoit l'article 130 TFUE au sujet de la BCE et des banques centrales nationales ?",o:["Elles ne peuvent solliciter ni recevoir d'instructions des institutions de l'Union ou des gouvernements des États membres","Elles reçoivent leurs instructions de l'Eurogroupe","Elles sont placées sous l'autorité de la Commission","Leurs dirigeants peuvent être révoqués à tout moment par le Conseil européen"],a:0,e:"Cette indépendance s'accompagne d'une obligation de rendre compte, notamment devant le Parlement européen.",u:["https://www.ecb.europa.eu/ecb/our-values/independence/html/index.fr.html"],s:"TFUE, art. 130"},
{id:"ue3-133",t:"ue",q:"Comment appelle-t-on la clause de l'article 125 TFUE selon laquelle ni l'Union ni un État membre ne répondent des engagements d'un autre État ?",o:["La clause de solidarité","La clause passerelle","La clause de flexibilité","La clause de non-renflouement (« no bail-out »)"],a:3,e:"Dans l'arrêt Pringle (2012), la Cour de justice a jugé le MES compatible avec cette clause, car son aide est soumise à une stricte conditionnalité.",u:["https://fr.wikipedia.org/wiki/Mécanisme_européen_de_stabilité"],s:"TFUE, art. 125"},
{id:"ue3-134",t:"ue",q:"Qui émet les pièces en euros ?",o:["La BCE seule","La Commission européenne","Les États membres, dans un volume soumis à l'approbation de la BCE","La Banque européenne d'investissement"],a:2,e:"La BCE est seule habilitée à autoriser l'émission des billets ; les pièces ont une face commune et une face nationale.",u:["https://www.ecb.europa.eu/euro/coins/html/index.fr.html"],s:"TFUE, art. 128"},
{id:"ue3-135",t:"ue",q:"Lequel de ces taux n'est pas un taux directeur de la BCE ?",o:["Le taux de la facilité de dépôt","Le taux du livret A","Le taux des opérations principales de refinancement","Le taux de la facilité de prêt marginal"],a:1,e:"Le taux du livret A est fixé en France selon une formule réglementaire.",u:["https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.fr.html"],s:"Banque UE"},
{id:"ue3-136",t:"ue",q:"Quel programme d'achats d'actifs la BCE a-t-elle lancé en mars 2020 face à la pandémie ?",o:["Le PEPP (programme d'achats d'urgence face à la pandémie)","Le MES","SURE","Le TSCG"],a:0,e:"Doté au total de 1 850 Md€ ; les achats nets ont pris fin en mars 2022.",u:["https://www.ecb.europa.eu/mopo/implement/pepp/html/index.fr.html"],s:"BCE, 18 mars 2020"},
{id:"ue3-137",t:"ue",q:"Quel président de la BCE a déclaré en juillet 2012 être prêt à faire « tout ce qu'il faudra » pour préserver l'euro ?",o:["Jean-Claude Trichet","Christine Lagarde","Wim Duisenberg","Mario Draghi"],a:3,e:"Ce discours, suivi de l'annonce du programme d'opérations monétaires sur titres (OMT), a apaisé la crise des dettes souveraines.",u:["https://fr.wikipedia.org/wiki/Mario_Draghi"],s:"Banque UE"},
{id:"ue3-138",t:"ue",q:"Pour quelle durée le président de l'Eurogroupe est-il élu ?",o:["Six mois","Deux ans et demi","Cinq ans","Huit ans"],a:1,e:"Élu à la majorité des États de la zone euro, parmi les ministres qui en sont membres (protocole n° 14).",u:["https://www.touteleurope.eu/economie-et-social/l-eurogroupe-organe-decisif-de-la-zone-euro/"],s:"Protocole n° 14"},
{id:"ue3-139",t:"ue",q:"Dans le cadre du semestre européen, qui adopte les recommandations par pays ?",o:["Le Conseil, sur recommandation de la Commission, après approbation par le Conseil européen","La BCE","Le Parlement européen","Chaque parlement national"],a:0,e:"Elles sont adoptées en juillet, à partir des propositions du paquet de printemps de la Commission.",u:["https://www.touteleurope.eu/economie-et-social/economie-et-budget-comment-les-etats-europeens-sont-ils-coordonnes/"],s:"Banque UE"},
{id:"ue3-140",t:"ue",q:"En quelle année le Pacte de stabilité et de croissance a-t-il été adopté ?",o:["1992","1997","2005","2011"],a:1,e:"Conseil européen d'Amsterdam (juin 1997) ; assoupli en 2005, renforcé en 2011 (six-pack) et 2013 (two-pack), réformé en 2024.",u:["https://www.touteleurope.eu/economie-et-social/qu-est-ce-que-le-pacte-de-stabilite-et-de-croissance/"],s:"Banque UE"},
{id:"ue3-141",t:"ue",q:"Comment appelle-t-on l'ensemble de cinq règlements et d'une directive adopté en 2011 pour renforcer la gouvernance économique européenne ?",o:["Le two-pack","Le TSCG","Le six-pack","Le pacte euro plus"],a:2,e:"Il a notamment créé la procédure concernant les déséquilibres macroéconomiques et le vote à la majorité qualifiée inversée pour certaines sanctions.",u:["https://www.touteleurope.eu/economie-et-social/qu-est-ce-que-le-pacte-de-stabilite-et-de-croissance/"],s:"Banque UE"},
{id:"ue3-142",t:"ue",q:"Sur quelle durée porte normalement la trajectoire d'ajustement des plans budgétaires et structurels nationaux à moyen terme issus de la réforme de 2024 ?",o:["Un an","Quatre ans, extensible à sept ans en contrepartie de réformes et d'investissements","Dix ans","Vingt ans"],a:1,e:"Règlement (UE) 2024/1263, entré en vigueur fin avril 2024.",u:["https://www.touteleurope.eu/economie-et-social/qu-est-ce-que-le-pacte-de-stabilite-et-de-croissance/"],s:"Règlement (UE) 2024/1263"},
{id:"ue3-143",t:"ue",q:"La réforme de 2024 du Pacte de stabilité a-t-elle modifié les valeurs de référence de 3 % et 60 % du PIB ?",o:["Oui : elles passent à 4 % et 90 %","Non : elles sont maintenues, car fixées par un protocole annexé aux traités","Oui : elles sont supprimées","Oui : seule la référence de dette passe à 100 %"],a:1,e:"Les modifier supposerait une révision des traités.",u:["https://www.touteleurope.eu/economie-et-social/qu-est-ce-que-le-pacte-de-stabilite-et-de-croissance/"],s:"Protocole n° 12"},
{id:"ue3-144",t:"ue",q:"Où siège le Mécanisme européen de stabilité (MES) ?",o:["Francfort","Bruxelles","Paris","Luxembourg"],a:3,e:"Il dispose d'une capacité de prêt de 500 Md€ pour aider, sous conditions, les États de la zone euro.",u:["https://fr.wikipedia.org/wiki/Mécanisme_européen_de_stabilité"],s:"Traité MES"},
{id:"ue3-145",t:"ue",q:"Sur quel fondement juridique repose le Mécanisme européen de stabilité ?",o:["Un règlement de l'Union","Un traité intergouvernemental conclu entre les États de la zone euro","Une directive","Une décision de la BCE"],a:1,e:"L'article 136 TFUE a été complété (décision du Conseil européen de mars 2011, entrée en vigueur en 2013) pour autoriser les États de la zone euro à instituer un tel mécanisme, octroyant une aide sous stricte conditionnalité.",u:["https://fr.wikipedia.org/wiki/Mécanisme_européen_de_stabilité"],s:"TFUE, art. 136 § 3"},
{id:"ue3-146",t:"ue",q:"Quel pilier de l'union bancaire n'était toujours pas en place au début de 2026 ?",o:["Le mécanisme de surveillance unique","Le mécanisme de résolution unique","Le système européen de garantie des dépôts","Le Fonds de résolution unique"],a:2,e:"Proposé par la Commission en novembre 2015, il n'avait toujours pas été adopté : les dépôts étaient garantis par des systèmes nationaux harmonisés, à hauteur de 100 000 € par déposant et par banque.",s:"Banque UE",act:1},
{id:"ue3-147",t:"ue",q:"Qui fut le premier haut représentant pour la PESC (« Monsieur PESC »), fonction créée par le traité d'Amsterdam ?",o:["Javier Solana","Catherine Ashton","Josep Borrell","Federica Mogherini"],a:0,e:"Il a exercé de 1999 à 2009 ; Catherine Ashton a été la première titulaire de la fonction renforcée par le traité de Lisbonne.",u:["https://fr.wikipedia.org/wiki/Javier_Solana"],s:"Banque UE"},
{id:"ue3-148",t:"ue",q:"Quel document adopté en mars 2022 fixe les orientations de l'Union en matière de sécurité et de défense pour la décennie ?",o:["Le livre blanc sur la défense et la sécurité nationale","Le concept stratégique de l'OTAN","La déclaration de Saint-Malo","La boussole stratégique"],a:3,e:"Elle prévoit notamment une capacité de déploiement rapide pouvant compter jusqu'à 5 000 militaires.",u:["https://fr.wikipedia.org/wiki/Boussole_stratégique"],s:"Conseil, mars 2022"},
{id:"ue3-149",t:"ue",q:"Quel instrument hors budget, créé en 2021, a notamment permis à l'Union de financer des équipements militaires pour l'Ukraine ?",o:["Le Fonds européen de développement régional","Le Mécanisme européen de stabilité","La facilité européenne pour la paix","Le programme Horizon Europe"],a:2,e:"Le budget de l'Union ne peut financer des dépenses ayant des implications militaires (art. 41 TUE) : la facilité est alimentée par des contributions des États.",u:["https://fr.wikipedia.org/wiki/Facilité_européenne_pour_la_paix"],s:"Décision (PESC) 2021/509"},
{id:"ue3-150",t:"ue",q:"Quel instrument de prêts de 150 Md€, adopté en 2025, soutient les achats communs d'équipements de défense par les États membres ?",o:["L'instrument SURE","L'instrument SAFE","Le programme InvestEU","Le plan REPowerEU"],a:1,e:"Il s'inscrit dans le plan « ReArm Europe » (« Readiness 2030 ») présenté par la Commission en mars 2025.",s:"Conseil, mai 2025"},
{id:"ue3-151",t:"ue",q:"Quelle clause prévoit que l'Union et ses États membres agissent conjointement lorsqu'un État est l'objet d'une attaque terroriste ou victime d'une catastrophe naturelle ou d'origine humaine ?",o:["La clause de solidarité (art. 222 TFUE)","La clause d'assistance mutuelle (art. 42 § 7 TUE)","La clause de retrait (art. 50 TUE)","La clause de flexibilité (art. 352 TFUE)"],a:0,e:"L'article 42 § 7 TUE vise l'agression armée sur le territoire d'un État membre ; la France l'a invoqué en novembre 2015.",s:"TFUE, art. 222"},
{id:"ue3-152",t:"ue",q:"Quelle opération navale de l'Union, lancée en 2008, lutte contre la piraterie au large de la Somalie ?",o:["Irini","Aspides","Sophia","Atalanta"],a:3,e:"Première opération navale de la PSDC. Irini contrôle l'embargo sur les armes à destination de la Libye ; Aspides protège la navigation en mer Rouge depuis 2024.",u:["https://fr.wikipedia.org/wiki/Opération_Atalante"],s:"Banque UE"},
{id:"ue3-153",t:"ue",q:"Quand la France a-t-elle réintroduit des contrôles à ses frontières intérieures, prolongés ensuite à plusieurs reprises ?",o:["Janvier 2002","Novembre 2015","Mars 2020","Janvier 2025"],a:1,e:"Rétablis pour la COP21 puis maintenus après les attentats du 13 novembre 2015 ; le code frontières Schengen ne les autorise qu'à titre temporaire et en dernier recours.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/le-fonctionnement-de-l-espace-schengen/"],s:"Code frontières Schengen"},
{id:"ue3-154",t:"ue",q:"Selon le système de Dublin, quel État est en principe responsable de l'examen d'une demande d'asile en l'absence de liens familiaux ou de titre de séjour ?",o:["L'État par lequel le demandeur est entré irrégulièrement dans l'Union","L'État choisi librement par le demandeur","L'État le plus peuplé de l'Union","L'Agence de l'Union européenne pour l'asile"],a:0,e:"Règle du règlement Dublin III (2013), reprise dans le règlement sur la gestion de l'asile et de la migration du pacte de 2024.",u:["https://www.touteleurope.eu/societe/asile-et-migrations-dans-l-union-europeenne/"],s:"Règlement (UE) n° 604/2013"},
{id:"ue3-155",t:"ue",q:"Quel ensemble de textes, adopté en mai 2024, réforme le régime d'asile européen, notamment le système de Dublin ?",o:["Le code frontières Schengen","Le paquet « Ajustement à l'objectif 55 »","Le pacte sur la migration et l'asile","Le six-pack"],a:2,e:"Il prévoit un filtrage aux frontières extérieures, une procédure à la frontière et un mécanisme de solidarité obligatoire mais flexible entre États.",u:["https://www.touteleurope.eu/societe/que-contient-le-pacte-europeen-sur-la-migration-et-l-asile/"],s:"Banque UE"},
{id:"ue3-156",t:"ue",q:"Qu'est-ce qu'Eurodac ?",o:["Une monnaie numérique de la BCE","Une base de données d'empreintes digitales des demandeurs d'asile et de certains migrants en situation irrégulière","Une agence européenne de notation financière","Un programme d'échanges universitaires"],a:1,e:"Elle sert notamment à déterminer l'État responsable de l'examen d'une demande d'asile.",u:["https://fr.wikipedia.org/wiki/Eurodac"],s:"Banque UE"},
{id:"ue3-157",t:"ue",q:"Quel système permet aux autorités des États Schengen d'échanger des signalements sur des personnes recherchées ou disparues et des objets volés ?",o:["Eurodac","Le système d'information sur les visas (VIS)","Le système d'échange d'informations sur la TVA (VIES)","Le système d'information Schengen (SIS)"],a:3,e:"C'est le système d'information le plus utilisé en Europe pour la sécurité et la gestion des frontières.",u:["https://fr.wikipedia.org/wiki/Système_d'information_Schengen"],s:"Banque UE"},
{id:"ue3-158",t:"ue",q:"Quel instrument, issu d'une décision-cadre de 2002, a remplacé l'extradition entre les États membres ?",o:["La notice rouge d'Interpol","Le mandat d'arrêt européen","La décision d'enquête européenne","Le mandat de dépôt"],a:1,e:"Remise directe d'autorité judiciaire à autorité judiciaire, sans contrôle de la double incrimination pour 32 catégories d'infractions graves ; applicable depuis 2004.",u:["https://fr.wikipedia.org/wiki/Mandat_d'arrêt_européen"],s:"Décision-cadre 2002/584/JAI"},
{id:"ue3-159",t:"ue",q:"Le Parquet européen est compétent pour les fraudes transfrontalières à la TVA lorsque le préjudice total atteint au moins :",o:["1 M€","10 M€","100 M€","1 Md€"],a:1,e:"Directive « PIF » (UE) 2017/1371 : fraudes liées au territoire d'au moins deux États membres et causant un préjudice d'au moins 10 M€.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/qu-est-ce-que-le-parquet-europeen/"],s:"Directive (UE) 2017/1371"},
{id:"ue3-160",t:"ue",q:"Combien de principes compte le socle européen des droits sociaux proclamé en 2017 ?",o:["10","20","27","50"],a:1,e:"Répartis en trois chapitres : égalité des chances et accès au marché du travail, conditions de travail équitables, protection et inclusion sociales.",u:["https://www.touteleurope.eu/economie-et-social/qu-est-ce-que-le-socle-europeen-des-droits-sociaux/"],s:"Socle européen des droits sociaux"},
{id:"ue3-161",t:"ue",q:"Quel objectif de taux d'emploi des 20-64 ans l'Union s'est-elle fixé pour 2030 (plan d'action du socle, sommet de Porto de 2021) ?",o:["65 %","70 %","78 %","90 %"],a:2,e:"Autres objectifs : 60 % des adultes en formation chaque année et 15 millions de personnes en moins menacées de pauvreté ou d'exclusion sociale.",u:["https://www.touteleurope.eu/economie-et-social/social-quel-bilan-pour-le-sommet-europeen-de-porto/"],s:"Sommet de Porto, mai 2021"},
{id:"ue3-162",t:"ue",q:"La directive de 2022 relative à des salaires minimaux adéquats oblige-t-elle chaque État à instaurer un salaire minimum légal ?",o:["Oui, à un niveau identique dans toute l'Union","Oui, fixé à 1 500 € par mois","Non : elle encadre l'adéquation des salaires minimaux légaux là où ils existent et promeut la négociation collective","Elle supprime les salaires minimaux nationaux"],a:2,e:"Directive (UE) 2022/2041 ; les États où la couverture des conventions collectives est inférieure à 80 % doivent établir un plan d'action.",x:"Le 11 novembre 2025, la Cour de justice a annulé deux dispositions de l'article 5 (critères de fixation des salaires minimaux légaux, interdiction de les réduire en cas d'indexation automatique) et validé le reste de la directive.",u:["https://www.touteleurope.eu/economie-et-social/le-salaire-minimum-en-europe/"],s:"Directive (UE) 2022/2041"},
{id:"ue3-163",t:"ue",q:"Quelle directive de 2023, à transposer au plus tard en juin 2026, vise à renforcer l'égalité de rémunération entre les femmes et les hommes ?",o:["La directive sur la transparence des rémunérations","La directive sur le détachement de travailleurs","La directive « services »","La directive sur le temps de travail"],a:0,e:"Directive (UE) 2023/970 : information sur les rémunérations, rapports sur les écarts salariaux, renversement de la charge de la preuve.",u:["https://www.touteleurope.eu/economie-et-social/les-inegalites-salariales-entre-les-femmes-et-les-hommes-en-europe/"],s:"Directive (UE) 2023/970"},
{id:"ue3-164",t:"ue",q:"Selon la directive 2003/88/CE sur le temps de travail, la durée moyenne hebdomadaire de travail, heures supplémentaires comprises, ne peut excéder :",o:["35 heures","40 heures","48 heures","60 heures"],a:2,e:"Elle garantit aussi un repos quotidien de 11 heures consécutives et quatre semaines de congés payés annuels.",s:"Directive 2003/88/CE"},
{id:"ue3-165",t:"ue",q:"Que prévoit la directive de 2024 relative à l'amélioration des conditions de travail via une plateforme ?",o:["L'interdiction des plateformes de livraison","Un statut d'indépendant obligatoire pour leurs travailleurs","La suppression du salaire minimum pour ces travailleurs","Une présomption légale d'emploi salarié lorsque des faits indiquent un contrôle et une direction exercés par la plateforme"],a:3,e:"Directive (UE) 2024/2831, à transposer d'ici décembre 2026 ; elle encadre aussi la gestion algorithmique.",u:["https://www.touteleurope.eu/economie-et-social/la-directive-sur-les-travailleurs-des-plateformes-numeriques-definitivement-adoptee-par-l-union-europeenne/"],s:"Directive (UE) 2024/2831"},
{id:"ue3-166",t:"ue",q:"De quelle organisation relève la Charte sociale européenne de 1961, révisée en 1996 ?",o:["De l'Union européenne","De l'Organisation internationale du travail","Du Conseil de l'Europe","De l'OCDE"],a:2,e:"Son respect est contrôlé par le Comité européen des droits sociaux ; ne pas la confondre avec la Charte communautaire des droits sociaux fondamentaux des travailleurs (1989).",u:["https://www.touteleurope.eu/l-ue-dans-le-monde/qu-est-ce-que-le-conseil-de-l-europe/"],s:"Banque UE"},
{id:"ue3-167",t:"ue",q:"Quel document permet à un assuré social d'accéder aux soins médicalement nécessaires lors d'un séjour temporaire dans un autre État membre ?",o:["La carte bleue européenne","La carte européenne d'assurance maladie","Le formulaire A1","Le passeport Europass"],a:1,e:"Le formulaire A1 atteste la législation de sécurité sociale applicable à un travailleur détaché ; la carte bleue européenne est un titre de séjour pour travailleurs hautement qualifiés de pays tiers.",u:["https://fr.wikipedia.org/wiki/Carte_européenne_d'assurance_maladie"],s:"Règlement (CE) n° 883/2004"},
{id:"ue3-168",t:"ue",q:"Quel texte a rendu juridiquement contraignants l'objectif de neutralité climatique en 2050 et la réduction d'au moins 55 % des émissions nettes en 2030 ?",o:["La loi européenne sur le climat (règlement de 2021)","L'accord de Paris de 2015","Le traité de Lisbonne","La directive de 2003 créant le SEQE-UE"],a:0,e:"Règlement (UE) 2021/1119 ; l'accord de Paris est un traité international qui ne fixe pas ces objectifs chiffrés propres à l'Union.",u:["https://www.touteleurope.eu/environnement/de-2030-a-2050-quels-sont-les-objectifs-climatiques-de-l-union-europeenne/"],s:"Règlement (UE) 2021/1119"},
{id:"ue3-169",t:"ue",q:"Comment s'appelle le paquet législatif présenté en juillet 2021 pour réduire les émissions nettes de gaz à effet de serre d'au moins 55 % en 2030 par rapport à 1990 ?",o:["REPowerEU","NextGenerationEU","Horizon Europe","« Ajustement à l'objectif 55 » (Fit for 55)"],a:3,e:"Il révise notamment le SEQE-UE et crée le mécanisme d'ajustement carbone aux frontières et le Fonds social pour le climat.",u:["https://www.touteleurope.eu/environnement/qu-est-ce-que-le-pacte-vert-pour-l-europe/"],s:"Commission, juillet 2021"},
{id:"ue3-170",t:"ue",q:"Depuis quelle année le système d'échange de quotas d'émission de l'Union (SEQE-UE) fonctionne-t-il ?",o:["1997","2005","2015","2023"],a:1,e:"Premier grand marché du carbone au monde ; 1997 est l'année du protocole de Kyoto.",u:["https://www.touteleurope.eu/environnement/marche-du-carbone-comment-l-union-europeenne-met-un-prix-sur-la-pollution/"],s:"Directive 2003/87/CE"},
{id:"ue3-171",t:"ue",q:"Sur quel principe repose le SEQE-UE ?",o:["Un plafond d'émissions décroissant et l'échange de quotas entre installations","Une taxe carbone uniforme payée par les ménages","L'interdiction progressive de toutes les énergies fossiles","Une subvention versée aux centrales à charbon"],a:0,e:"Chaque installation doit restituer autant de quotas que de tonnes de CO2 émises ; elle peut en acheter ou en vendre.",u:["https://www.touteleurope.eu/environnement/marche-du-carbone-comment-l-union-europeenne-met-un-prix-sur-la-pollution/"],s:"Directive 2003/87/CE"},
{id:"ue3-172",t:"ue",q:"Quel secteur a été intégré au SEQE-UE à partir de 2024 ?",o:["L'agriculture","Le logement social","Le transport maritime","La santé"],a:2,e:"Le SEQE couvre déjà la production d'électricité, l'industrie lourde et l'aviation intra-européenne ; un second système (SEQE 2) doit couvrir les bâtiments et le transport routier.",u:["https://www.touteleurope.eu/environnement/marche-du-carbone-comment-l-union-europeenne-met-un-prix-sur-la-pollution/"],s:"Directive (UE) 2023/959"},
{id:"ue3-173",t:"ue",q:"Quels produits importés sont couverts par le mécanisme d'ajustement carbone aux frontières (MACF) ?",o:["Les textiles et les chaussures","Le ciment, le fer et l'acier, l'aluminium, les engrais, l'électricité et l'hydrogène","Les produits agricoles bruts","Les logiciels et services numériques"],a:1,e:"Règlement (UE) 2023/956 : l'importateur doit acquérir des certificats correspondant au prix du carbone dans le SEQE-UE.",u:["https://www.touteleurope.eu/environnement/climat-comment-fonctionne-la-taxe-carbone-aux-frontieres-de-l-union-europeenne/"],s:"Règlement (UE) 2023/956"},
{id:"ue3-174",t:"ue",q:"Quel est l'objectif principal du mécanisme d'ajustement carbone aux frontières ?",o:["Taxer les exportations européennes vers les pays tiers","Remplacer la TVA à l'importation","Financer la politique agricole commune","Prévenir les « fuites de carbone » en appliquant aux importations un prix du carbone équivalent à celui payé par les producteurs européens"],a:3,e:"Il accompagne la suppression progressive des quotas gratuits alloués aux industries concernées dans le SEQE-UE.",u:["https://www.touteleurope.eu/environnement/climat-comment-fonctionne-la-taxe-carbone-aux-frontieres-de-l-union-europeenne/"],s:"Règlement (UE) 2023/956"},
{id:"ue3-175",t:"ue",q:"Quel objectif contraignant de part des énergies renouvelables dans la consommation finale d'énergie l'Union s'est-elle fixé pour 2030 (directive révisée en 2023) ?",o:["20 %","32 %","42,5 %","75 %"],a:2,e:"Avec l'ambition d'atteindre 45 % ; l'objectif était de 20 % pour 2020, puis de 32 % pour 2030 dans la directive de 2018.",u:["https://www.touteleurope.eu/environnement/les-energies-renouvelables-dans-l-ue/"],s:"Directive (UE) 2023/2413"},
{id:"ue3-176",t:"ue",q:"Quel plan, présenté en mai 2022, vise à mettre fin à la dépendance de l'Union aux combustibles fossiles russes ?",o:["« Ajustement à l'objectif 55 »","REPowerEU","InvestEU","Global Gateway"],a:1,e:"Économies d'énergie, diversification des approvisionnements et accélération des renouvelables ; il a été financé en partie via la facilité pour la reprise et la résilience.",u:["https://www.touteleurope.eu/environnement/repowereu-comment-l-union-europeenne-veut-sortir-de-sa-dependance-aux-energies-fossiles-russes/"],s:"Commission, mai 2022"},
{id:"ue3-177",t:"ue",q:"Qu'est-ce que la taxonomie européenne établie par un règlement de 2020 ?",o:["Une liste des taxes européennes","Un classement des États selon leur dette","Une classification des activités économiques considérées comme durables sur le plan environnemental","Une nomenclature douanière"],a:2,e:"Règlement (UE) 2020/852 ; certaines activités nucléaires et gazières y ont été intégrées sous conditions en 2022.",s:"Règlement (UE) 2020/852"},
{id:"ue3-178",t:"ue",q:"Selon l'article 194 TFUE, la politique énergétique de l'Union n'affecte pas le droit d'un État membre :",o:["De déterminer la structure générale de son approvisionnement énergétique (son bouquet énergétique)","De fixer librement les droits de douane sur le gaz importé","D'accorder des aides d'État sans contrôle de la Commission","De refuser l'application des règles du marché intérieur de l'électricité"],a:0,e:"Chaque État choisit notamment entre nucléaire, gaz ou renouvelables ; l'énergie est une compétence partagée.",u:["https://www.touteleurope.eu/environnement/l-energie-dans-l-union-europeenne/"],s:"TFUE, art. 194"},
{id:"ue3-179",t:"ue",q:"Lequel de ces principes est inscrit à l'article 191 TFUE pour la politique de l'environnement ?",o:["Le principe de non-renflouement","Le principe d'annualité","Le principe de reconnaissance mutuelle","Le principe du pollueur-payeur"],a:3,e:"Art. 191 § 2 : principes de précaution, d'action préventive, de correction à la source et du pollueur-payeur.",u:["https://www.touteleurope.eu/environnement/la-politique-europeenne-de-l-environnement-et-du-climat/"],s:"TFUE, art. 191"},
{id:"ue3-180",t:"ue",q:"Sur quelles directives repose le réseau Natura 2000 ?",o:["La directive TVA et la directive « services »","La seule directive-cadre sur l'eau","Les directives « Oiseaux » (1979) et « Habitats » (1992)","Les directives sur les énergies renouvelables"],a:2,e:"Le réseau protège des espèces et des habitats naturels d'intérêt européen.",u:["https://fr.wikipedia.org/wiki/Réseau_Natura_2000"],s:"Banque UE"},
{id:"ue3-181",t:"ue",q:"Selon le mécanisme du « guichet unique » du RGPD, quelle autorité est chef de file pour un traitement transfrontalier ?",o:["La Commission européenne","L'autorité de contrôle de l'État où se trouve l'établissement principal du responsable du traitement","La CNIL dans tous les cas","L'autorité de l'État le plus peuplé"],a:1,e:"D'où le rôle de l'autorité irlandaise pour plusieurs grandes plateformes ; le Comité européen de la protection des données tranche les désaccords.",u:["https://www.touteleurope.eu/l-europe-et-moi/l-europe-et-la-protection-des-donnees-personnelles-en-3-minutes/"],s:"RGPD, art. 56"},
{id:"ue3-182",t:"ue",q:"Quel dispositif de transfert de données vers les États-Unis la Cour de justice a-t-elle invalidé en juillet 2020 (arrêt Schrems II) ?",o:["Le bouclier de protection des données (Privacy Shield)","La sphère de sécurité (Safe Harbor)","Le cadre de protection des données UE-États-Unis (Data Privacy Framework)","Les clauses contractuelles types"],a:0,e:"Le Safe Harbor avait été invalidé en 2015 (Schrems I) ; le Data Privacy Framework a fait l'objet d'une décision d'adéquation en 2023. Les clauses contractuelles types ont été jugées valides.",u:["https://fr.wikipedia.org/wiki/Bouclier_de_protection_des_données_UE-États-Unis"],s:"CJUE, 16 juillet 2020"},
{id:"ue3-183",t:"ue",q:"Dans quel arrêt de 2014 la Cour de justice a-t-elle reconnu un droit au déréférencement (« droit à l'oubli ») face aux moteurs de recherche ?",o:["Schrems","Digital Rights Ireland","Costa contre ENEL","Google Spain"],a:3,e:"CJUE, 13 mai 2014 ; ce droit figure désormais à l'article 17 du RGPD (droit à l'effacement).",u:["https://fr.wikipedia.org/wiki/Droit_à_l'oubli"],s:"CJUE, 13 mai 2014"},
{id:"ue3-184",t:"ue",q:"Combien de niveaux de risque le règlement européen sur l'intelligence artificielle distingue-t-il ?",o:["Deux","Quatre","Six","Dix"],a:1,e:"Risque inacceptable (interdit), haut risque (obligations strictes), risque limité (obligations de transparence) et risque minimal.",u:["https://www.touteleurope.eu/economie-et-social/podcast-intelligence-artificielle-quelles-sont-les-principales-mesures-du-reglement-europeen-ia-act/"],s:"Règlement (UE) 2024/1689"},
{id:"ue3-186",t:"ue",q:"Quel taux normal minimal de TVA la directive 2006/112/CE impose-t-elle aux États membres ?",o:["5 %","10 %","15 %","20 %"],a:2,e:"Les taux réduits ne peuvent en principe être inférieurs à 5 % ; une réforme de 2022 a élargi les possibilités de taux réduits.",u:["https://www.touteleurope.eu/economie-et-social/les-taux-de-tva-dans-l-ue/"],s:"Directive 2006/112/CE"},
{id:"ue3-187",t:"ue",q:"Au début de 2026, quel État membre appliquait le taux normal de TVA le plus élevé de l'Union, 27 % ?",o:["Le Danemark","La France","La Hongrie","Le Luxembourg"],a:2,e:"Taux en vigueur depuis le 1er janvier 2012. Le Luxembourg appliquait alors le taux normal le plus bas (17 %) ; le taux normal français est de 20 %, celui du Danemark de 25 %.",u:["https://www.touteleurope.eu/economie-et-social/les-taux-de-tva-dans-l-ue/"],s:"Banque UE",act:1},
{id:"ue3-188",t:"ue",q:"Dans le régime de TVA intracommunautaire entre assujettis, une livraison de biens expédiés vers un autre État membre est en principe :",o:["Taxée à la fois dans l'État de départ et dans l'État d'arrivée","Exonérée dans l'État de départ et taxée dans l'État d'arrivée au titre d'une acquisition intracommunautaire","Taxée uniquement dans l'État de départ","Exonérée dans les deux États"],a:1,e:"Ce régime dit « transitoire », en vigueur depuis le 1er janvier 1993, a accompagné la suppression des contrôles aux frontières intérieures.",u:["https://european-union.europa.eu/priorities-and-actions/actions-topic/taxation_fr"],s:"Directive 2006/112/CE"},
{id:"ue3-189",t:"ue",q:"Comment appelle-t-on la fraude à la TVA intracommunautaire dans laquelle un opérateur acquiert des biens en exonération, les revend en facturant la TVA puis disparaît sans la reverser ?",o:["Le dumping fiscal","La manipulation des prix de transfert","L'optimisation fiscale agressive","La fraude carrousel (fraude à l'opérateur défaillant)"],a:3,e:"Les biens circulent souvent entre plusieurs États ; les cas les plus graves (au moins deux États et 10 M€ de préjudice) relèvent du Parquet européen.",u:["https://fr.wikipedia.org/wiki/Fraude_à_la_TVA"],s:"Banque UE"},
{id:"ue3-190",t:"ue",q:"Depuis le 1er juillet 2021, au-delà de quel montant annuel de ventes à distance intracommunautaires de biens à des particuliers la TVA est-elle due dans l'État de destination ?",o:["10 000 € pour l'ensemble de l'Union","35 000 € par État de destination","100 000 € par État de destination","1 M€ pour l'ensemble de l'Union"],a:0,e:"Le vendeur peut déclarer et payer la TVA due dans les autres États via le guichet unique (OSS) de son pays.",s:"Directive (UE) 2017/2455"},
{id:"ue3-191",t:"ue",q:"Quel système permet de vérifier la validité d'un numéro d'identification à la TVA intracommunautaire ?",o:["SIS","VIES","Eurodac","TARIC"],a:1,e:"Système d'échange d'informations sur la TVA ; TARIC est le tarif intégré de l'Union.",s:"Règlement (UE) n° 904/2010"},
{id:"ue3-192",t:"ue",q:"Quel paquet adopté en mars 2025 prévoit la facturation électronique et la déclaration numérique des opérations intracommunautaires entre entreprises à partir de 2030 ?",o:["DAC 8","Le Pilier 2","« La TVA à l'ère numérique » (ViDA)","BEFIT"],a:2,e:"Il adapte aussi les règles de TVA à l'économie des plateformes et étend le guichet unique.",s:"Conseil, mars 2025"},
{id:"ue3-193",t:"ue",q:"Quel est l'objet de la directive dite DAC 6 (2018) ?",o:["Obliger les intermédiaires à déclarer les dispositifs transfrontières de planification fiscale potentiellement agressive","Instaurer une imposition minimale des grands groupes","Organiser l'échange d'informations sur les crypto-actifs","Réformer la TVA du commerce électronique"],a:0,e:"Elle modifie la directive 2011/16/UE sur la coopération administrative ; les informations sont échangées automatiquement entre administrations.",s:"Directive (UE) 2018/822"},
{id:"ue3-194",t:"ue",q:"Quelle directive oblige depuis 2023 les opérateurs de plateformes numériques à déclarer les revenus perçus par leurs vendeurs ?",o:["DAC 6","ATAD","NIS 2","DAC 7"],a:3,e:"Directive (UE) 2021/514 : ventes de biens, locations, services personnels… ; en France, ces déclarations sont adressées à la DGFiP.",s:"Directive (UE) 2021/514"},
{id:"ue3-195",t:"ue",q:"Quel est l'objet principal de la directive DAC 8 (2023) ?",o:["Les revenus tirés des plateformes de location","Les comptes bancaires détenus à l'étranger","L'échange automatique d'informations sur les transactions en crypto-actifs","Les rescrits fiscaux transfrontières"],a:2,e:"Directive (UE) 2023/2226, applicable depuis le 1er janvier 2026.",s:"Directive (UE) 2023/2226"},
{id:"ue3-196",t:"ue",q:"La directive ATAD (2016) limite notamment la déductibilité des surcoûts d'emprunt à :",o:["10 % du chiffre d'affaires","30 % de l'EBITDA fiscal, avec une franchise pouvant aller jusqu'à 3 M€","50 % du résultat comptable","100 % des intérêts versés à des tiers"],a:1,e:"Elle prévoit aussi une clause anti-abus générale, des règles sur les sociétés étrangères contrôlées, l'imposition à la sortie et les dispositifs hybrides.",s:"Directive (UE) 2016/1164"},
{id:"ue3-197",t:"ue",q:"La directive « Pilier 2 » du 15 décembre 2022 transpose dans l'Union des règles élaborées dans le cadre :",o:["Du cadre inclusif de l'OCDE et du G20","De l'Organisation mondiale du commerce","Du Fonds monétaire international","De la Banque mondiale"],a:0,e:"Directive (UE) 2022/2523, adoptée à l'unanimité : taux effectif minimal de 15 % pour les groupes réalisant au moins 750 M€ de chiffre d'affaires.",u:["https://european-union.europa.eu/priorities-and-actions/actions-topic/taxation_fr"],s:"Directive (UE) 2022/2523"},
{id:"ue3-198",t:"ue",q:"Par qui et à quel rythme la liste de l'Union des pays et territoires non coopératifs à des fins fiscales est-elle révisée ?",o:["Par la Cour de justice, chaque année","Par l'OCDE, tous les cinq ans","Par le Parlement européen, à chaque législature","Par le Conseil de l'UE, deux fois par an"],a:3,e:"Créée en décembre 2017, elle repose sur des critères de transparence fiscale, de concurrence fiscale équitable et de lutte contre l'érosion de la base d'imposition.",u:["https://www.touteleurope.eu/economie-et-social/paradis-fiscaux-la-liste-de-l-union-europeenne/"],s:"Conseil, 2017"},
{id:"ue3-199",t:"ue",q:"Selon l'arrêt Cadbury Schweppes (2006), une législation nationale anti-abus qui restreint la liberté d'établissement n'est justifiée que si elle vise :",o:["Les montages purement artificiels destinés à éluder l'impôt normalement dû","Toutes les filiales établies dans un autre État membre","Les seules petites et moyennes entreprises","Les seules sociétés cotées en bourse"],a:0,e:"La simple implantation dans un État à fiscalité plus faible ne suffit pas à présumer une fraude.",s:"CJCE, 2006, Cadbury Schweppes"},
{id:"ue3-200",t:"ue",q:"L'arrêt Åkerberg Fransson (2013) concerne l'application de la Charte des droits fondamentaux, et notamment du principe ne bis in idem, à :",o:["Des quotas laitiers","Des transferts de footballeurs","Des sanctions fiscales et pénales en matière de TVA","Des transferts de données personnelles"],a:2,e:"La Cour juge que la répression des fraudes à la TVA met en œuvre le droit de l'Union : la Charte s'applique donc.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/la-charte-des-droits-fondamentaux-de-l-union-europeenne/"],s:"CJUE, 2013"},
{id:"ue3-201",t:"ue",q:"Lequel de ces intitulés n'est pas un titre de la Charte des droits fondamentaux de l'Union ?",o:["Dignité","Propriété","Solidarité","Citoyenneté"],a:1,e:"Titres : Dignité, Libertés, Égalité, Solidarité, Citoyenneté, Justice, puis dispositions générales. Le droit de propriété figure au titre Libertés (art. 17).",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/la-charte-des-droits-fondamentaux-de-l-union-europeenne/"],s:"Charte des droits fondamentaux"},
{id:"ue3-202",t:"ue",q:"Combien d'articles la Charte des droits fondamentaux de l'Union compte-t-elle ?",o:["30","54","89","120"],a:1,e:"Répartis en sept titres ; elle a la même valeur juridique que les traités depuis le 1er décembre 2009.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/la-charte-des-droits-fondamentaux-de-l-union-europeenne/"],s:"Charte des droits fondamentaux"},
{id:"ue3-203",t:"ue",q:"Selon son article 51, à qui la Charte des droits fondamentaux s'adresse-t-elle ?",o:["Aux États membres dans tous leurs domaines d'action","Aux seuls particuliers","Aux seuls États de la zone euro","Aux institutions de l'Union, et aux États membres uniquement lorsqu'ils mettent en œuvre le droit de l'Union"],a:3,e:"Elle n'étend pas les compétences de l'Union.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/la-charte-des-droits-fondamentaux-de-l-union-europeenne/"],s:"Charte, art. 51"},
{id:"ue3-204",t:"ue",q:"Quels États ont obtenu un protocole (n° 30) sur l'application de la Charte des droits fondamentaux à leur égard ?",o:["La France et l'Allemagne","La Pologne et le Royaume-Uni","L'Irlande et le Danemark","La Hongrie et la Slovaquie"],a:1,e:"La Cour de justice a jugé qu'il ne s'agissait pas d'une exemption générale (arrêt N. S., 2011).",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/la-charte-des-droits-fondamentaux-de-l-union-europeenne/"],s:"Protocole n° 30"},
{id:"ue3-205",t:"ue",q:"La Charte des droits fondamentaux de l'Union interdit-elle la peine de mort ?",o:["Non, elle n'aborde pas cette question","Seulement en temps de paix","Oui : nul ne peut être condamné à la peine de mort, ni exécuté (art. 2)","Seulement pour les mineurs"],a:2,e:"La Convention européenne des droits de l'homme l'interdit aussi, par ses protocoles n° 6 (en temps de paix) et n° 13 (en toutes circonstances).",u:["https://www.touteleurope.eu/societe/carte-l-abolition-de-la-peine-de-mort-en-europe/"],s:"Charte, art. 2"},
{id:"ue3-206",t:"ue",q:"Lequel de ces droits, absent du texte de la Convention européenne des droits de l'homme de 1950, figure expressément dans la Charte des droits fondamentaux de l'Union ?",o:["Le droit à une bonne administration","Le droit à la vie","L'interdiction de la torture","Le droit à un procès équitable"],a:0,e:"Art. 41 de la Charte ; elle consacre aussi la protection des données à caractère personnel (art. 8).",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/la-charte-des-droits-fondamentaux-de-l-union-europeenne/"],s:"Charte, art. 41"},
{id:"ue3-207",t:"ue",q:"Quel article du TUE prévoit l'adhésion de l'Union à la Convention européenne des droits de l'homme ?",o:["L'article 2","L'article 7","L'article 49","L'article 6 § 2"],a:3,e:"L'article 6 § 1 donne à la Charte la même valeur que les traités ; le § 3 fait des droits fondamentaux des principes généraux du droit de l'Union.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/le-traite-sur-l-union-europeenne-tue/"],s:"TUE, art. 6"},
{id:"ue3-208",t:"ue",q:"Qu'a jugé la Cour de justice dans son avis 2/13 du 18 décembre 2014 ?",o:["Que l'adhésion de l'Union à la CEDH était achevée","Que la Charte était contraire à la Convention","Que le projet d'accord d'adhésion de l'Union à la CEDH était incompatible avec les traités","Que la Convention ne s'appliquait plus aux États membres"],a:2,e:"La Cour y voyait notamment une atteinte à l'autonomie du droit de l'Union ; les négociations ont repris en 2020.",u:["https://www.touteleurope.eu/institutions/quelle-est-la-difference-entre-la-cour-de-justice-de-l-union-europeenne-cjue-et-la-cour-europeenne-des-droits-de-l-homme-cedh/"],s:"CJUE, avis 2/13"},
{id:"ue3-209",t:"ue",q:"Au début de 2026, l'Union européenne avait-elle adhéré à la Convention européenne des droits de l'homme ?",o:["Oui, depuis le 1er décembre 2009","Non : l'adhésion prévue par le traité de Lisbonne n'avait pas abouti","Oui, depuis 2014","Oui, depuis la création du Conseil de l'Europe"],a:1,e:"L'article 6 § 2 TUE prévoit cette adhésion, mais la Cour de justice a jugé le premier projet d'accord incompatible avec les traités (avis 2/13, 2014). Tous les États membres de l'Union sont en revanche parties à la Convention.",u:["https://www.touteleurope.eu/l-ue-dans-le-monde/la-convention-et-la-cour-europeennes-des-droits-de-l-homme-cedh/"],s:"TUE, art. 6 § 2",act:1},
{id:"ue3-210",t:"ue",q:"Depuis quand les justiciables français peuvent-ils saisir individuellement la Cour européenne des droits de l'homme ?",o:["1950","1974","1981","2000"],a:2,e:"La France a ratifié la Convention en 1974 mais n'a accepté le droit de recours individuel qu'en 1981.",u:["https://www.touteleurope.eu/l-ue-dans-le-monde/la-convention-et-la-cour-europeennes-des-droits-de-l-homme-cedh/"],s:"Banque UE"},
{id:"ue3-211",t:"ue",q:"Qui élit les juges de la Cour européenne des droits de l'homme ?",o:["L'Assemblée parlementaire du Conseil de l'Europe","Le Parlement européen","Le Conseil européen","L'Assemblée générale des Nations unies"],a:0,e:"Un juge par État partie, élu pour neuf ans non renouvelables sur une liste de trois candidats présentée par l'État.",u:["https://www.touteleurope.eu/l-ue-dans-le-monde/la-convention-et-la-cour-europeennes-des-droits-de-l-homme-cedh/"],s:"Convention EDH, art. 22"},
{id:"ue3-212",t:"ue",q:"Dans quel délai une requête doit-elle être introduite devant la Cour européenne des droits de l'homme après la décision interne définitive ?",o:["Deux mois","Quatre mois","Six mois","Un an"],a:1,e:"Délai réduit de six à quatre mois depuis le 1er février 2022 (protocole n° 15) ; le requérant doit avoir épuisé les voies de recours internes.",u:["https://www.touteleurope.eu/l-ue-dans-le-monde/la-convention-et-la-cour-europeennes-des-droits-de-l-homme-cedh/"],s:"Convention EDH, art. 35"},
{id:"ue3-213",t:"ue",q:"Que permet le protocole n° 16 à la Convention européenne des droits de l'homme, en vigueur depuis 2018 ?",o:["D'abolir la peine de mort en toutes circonstances","De créer une juridiction pénale européenne","D'exclure un État du Conseil de l'Europe","Aux plus hautes juridictions nationales de demander à la Cour un avis consultatif"],a:3,e:"La Cour de cassation française a été la première à l'utiliser, en 2018, au sujet de la gestation pour autrui.",s:"Protocole n° 16"},
{id:"ue3-214",t:"ue",q:"Quel organe du Conseil de l'Europe surveille l'exécution des arrêts de la Cour européenne des droits de l'homme ?",o:["Le Comité des ministres","L'Assemblée parlementaire","La Commission européenne","La Cour de justice de l'Union"],a:0,e:"Art. 46 de la Convention : les États s'engagent à se conformer aux arrêts définitifs rendus dans les litiges auxquels ils sont parties.",u:["https://www.touteleurope.eu/l-ue-dans-le-monde/qu-est-ce-que-le-conseil-de-l-europe/"],s:"Convention EDH, art. 46"},
{id:"ue3-215",t:"ue",q:"Quel organe consultatif du Conseil de l'Europe rend des avis sur les questions constitutionnelles et l'État de droit ?",o:["La Commission européenne","Le Comité européen des régions","La Commission de Venise","L'Agence des droits fondamentaux de l'Union"],a:2,e:"Commission européenne pour la démocratie par le droit, créée en 1990.",u:["https://fr.wikipedia.org/wiki/Commission_de_Venise"],s:"Banque UE"},
{id:"ue3-216",t:"ue",q:"Où siège l'Agence des droits fondamentaux de l'Union européenne (FRA), créée en 2007 ?",o:["Strasbourg","Vienne","Luxembourg","Genève"],a:1,e:"Elle apporte une expertise indépendante aux institutions et aux États ; elle a succédé à l'Observatoire européen des phénomènes racistes et xénophobes.",u:["https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/european-union-agency-fundamental-rights-fra_fr"],s:"Règlement (CE) n° 168/2007"},
{id:"ue3-217",t:"ue",q:"Quelle institution a déclenché en septembre 2018 la procédure de l'article 7 § 1 TUE à l'encontre de la Hongrie ?",o:["La Commission européenne","La Cour de justice","Le Conseil européen","Le Parlement européen"],a:3,e:"Contre la Pologne, la procédure avait été engagée par la Commission en décembre 2017, avant d'être close en 2024.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/violation-des-valeurs-de-l-ue-comment-fonctionne-la-procedure-de-sanctions-article-7/"],s:"Parlement européen, 12 septembre 2018"},
{id:"ue3-218",t:"ue",q:"Quel document la Commission publie-t-elle chaque année depuis 2020 pour évaluer, dans chaque État membre, la justice, la lutte contre la corruption, la liberté des médias et les contre-pouvoirs ?",o:["Le rapport sur la convergence","Le rapport sur l'État de droit","Le rapport sur la compétitivité","Les recommandations par pays du semestre européen"],a:1,e:"Outil préventif, distinct de la procédure de l'article 7 et du règlement de conditionnalité.",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/l-etat-de-droit-est-une-valeur-des-etats-europeens-et-de-l-union-europeenne/"],s:"Commission, depuis 2020"},
{id:"ue3-219",t:"ue",q:"En octobre 2021, la Cour de justice a condamné la Pologne à une astreinte d'un million d'euros par jour en lien avec :",o:["Son refus d'adopter l'euro","La pollution de l'air dans ses grandes villes","Le régime disciplinaire applicable aux juges","Le non-respect des quotas laitiers"],a:2,e:"La Pologne n'avait pas suspendu l'activité de la chambre disciplinaire de sa Cour suprême ; l'astreinte a été réduite de moitié en 2023.",s:"CJUE, ordonnance du 27 octobre 2021"},
// --- Actualité : budget européen et politique monétaire en 2026 (vérifié le 17 oct. 2026) ---
{id:"act27-13",t:"ue",q:"Quel montant de contribution française au budget de l'Union européenne pour 2027 l'Assemblée nationale a-t-elle adopté le 14 octobre 2026 ?",o:["24,9 Md€","28,4 Md€","30,9 Md€","35,2 Md€"],a:2,e:"L'article 55 du PLF évalue le prélèvement sur recettes au profit de l'UE à 30,9 Md€ ; il a été adopté par 111 voix contre 93. Il était d'environ 28,4 Md€ en LFI 2026.",x:"Ce vote porte sur une évaluation : le montant dû découle du budget de l'UE et des règles relatives aux ressources propres. La hausse tient à l'accélération des paiements en fin de cadre 2021-2027, au soutien à l'Ukraine et aux intérêts de l'emprunt NextGenerationEU.",u:["https://www.touteleurope.eu/economie-et-social/budget-europeen-l-assemblee-nationale-approuve-une-contribution-francaise-de-309-milliards-d-euros-pour-2027/","https://presse.economie.gouv.fr/dp-budget-2027/"],s:"Toute l'Europe (15 oct. 2026)",act:1},
{id:"act27-14",t:"ue",q:"Quel montant total la Commission européenne a-t-elle proposé en juillet 2025 pour le cadre financier pluriannuel 2028-2034 ?",o:["Environ 1 000 milliards d'euros","Environ 1 200 milliards d'euros","Environ 2 000 milliards d'euros","Environ 3 500 milliards d'euros"],a:2,e:"Soit 1,26 % du RNB de l'Union, dont 0,11 % pour rembourser l'emprunt NextGenerationEU ; le cadre 2021-2027 avoisine 1 200 Md€ hors plan de relance.",x:"Le 10 octobre 2026, la présidence irlandaise a proposé de ramener l'enveloppe à 1 825 Md€. Le règlement est adopté à l'unanimité par le Conseil, après approbation du Parlement européen (art. 312 TFUE).",u:["https://www.touteleurope.eu/fonctionnement-de-l-ue/budget-de-l-union-europeenne-la-commission-devoile-un-cadre-financier-de-2-000-milliards-d-euros-pour-la-periode-2028-2034/","https://www.touteleurope.eu/economie-et-social/conseil-europeen-la-france-pousse-pour-faire-adopter-rapidement-le-budget-la-competitivite-de-l-ue-au-coeur-des-debats/"],s:"Commission (16 juillet 2025) ; Toute l'Europe (16 oct. 2026)",act:1},
{id:"act27-15",t:"ue",q:"Quel est le taux de la facilité de dépôt de la Banque centrale européenne depuis le 16 septembre 2026 ?",o:["2,00 %","2,25 %","2,50 %","4,00 %"],a:2,e:"Le Conseil des gouverneurs l'a relevé de 25 points de base le 10 septembre 2026, après une première hausse à 2,25 % en juin 2026 ; il était de 2,00 % depuis juin 2025.",x:"Ces hausses répondent aux tensions sur l'inflation liées au conflit au Moyen-Orient et aux prix de l'énergie. La BCE pilote l'orientation de sa politique monétaire par ce taux ; celui des opérations principales de refinancement est fixé à 2,65 %.",u:["https://www.ecb.europa.eu/stats/policy_and_exchange_rates/key_ecb_interest_rates/html/index.fr.html","https://www.banque-france.fr/fr/communiques-de-presse/declaration-de-politique-monetaire-15"],s:"BCE, décision du 10 septembre 2026",act:1}
);
